"use strict";(self.webpackChunkwhaleal_home_site=self.webpackChunkwhaleal_home_site||[]).push([[296],{1111:function(e,a,t){t.r(a),t.d(a,{default:function(){return u}});var i=t(6540),o=t(4764),s=t(8959);const n={en:{terms:{title:"Terms of Service",meta:{updated:"Last updated: 2026-09-28",effective:"Effective: 2026-09-28"},blocks:[{t:"p",v:'This agreement governs your use of Whaleal Platform (the "Platform"). Registering or using the Platform means you have read and accepted it.'},{t:"h2",v:"1. What the Platform is"},{t:"li",v:"The Platform is a bring-your-own-keys (BYOL) multi-channel SMS relay: you supply your own CPaaS accounts and keys; the Platform provides key custody, routing, receipt handling and analytics."},{t:"li",v:"The Platform does not resell SMS or mark up carrier rates. Carrier charges stay in your own provider account. A paid plan may also pay a platform fee for usage past the included allowance (section 4)."},{t:"li",v:"The Platform never alters the underlying sending path: messages are forwarded as-is through the channel you designate. The Platform is not liable for send failures caused by the state of your own provider accounts (arrears, suspension, throttling)."},{t:"li",v:"The Platform does not guarantee delivery rates. Delivery belongs to channel and provider quality; the Platform presents receipt data faithfully."},{t:"h2",v:"2. Account & key security"},{t:"li",v:"You are responsible for safeguarding your Platform account, API keys and bound provider credentials, and for all activity occurring under them."},{t:"li",v:"Losses caused by credential leakage, lending or negligent custody (including resulting provider-side charges) are borne by you. On discovery, rotate keys immediately in the console."},{t:"li",v:"Provider credentials are stored encrypted with AES-256; encryption keys are managed separately from the data, decrypted only in memory at send time, and never written to disk or logs."},{t:"h2",v:"3. Your sending responsibilities"},{t:"li",v:"You warrant that your sending lists are lawfully sourced with all necessary consents, and you are solely responsible for the content you send and its legality, including opt-out handling and telecom compliance of each destination."},{t:"li",v:"Fines, complaints or legal liabilities arising from your failure to comply with destination-country regulations are borne by you."},{t:"li",v:"You warrant that all provider keys you bind are lawfully obtained and authorized for use by the provider."},{t:"li",v:"Registrations requiring provider-side review (templates, sender IDs) are completed by you in the provider portal; the Platform does not file on your behalf."},{t:"li",v:"Upon complaints, law-enforcement requests or clearly unlawful content, the Platform may suspend or terminate the sending capability of the relevant account and cooperate with investigations as required by law."},{t:"h2",v:"4. Subscription & billing"},{t:"li",v:"Subscriptions are processed via Stripe Checkout, monthly or yearly, and renew automatically each cycle until cancelled."},{t:"li",v:"You may cancel anytime from Plans & Billing in the console; cancellation takes effect at the end of the current cycle, with access intact until then."},{t:"li",v:"Paid subscription fees are non-refundable (except where mandatory law requires otherwise). The Free tier is available indefinitely so you can evaluate before upgrading."},{t:"li",v:"Failed payments enter a 7-day grace period; after that the account downgrades to Free."},{t:"li",v:"Connections are unlimited. Every plan includes monthly SMS segments and short-link clicks. Growth and above keep going past that allowance, pay a platform fee for the extra use, and include bulk SMS and short-link import. Carrier SMS charges stay in your own provider account. WhatsApp and email are included."},{t:"h2",v:"5. Service availability"},{t:"p",v:"The Platform does not guarantee uninterrupted or error-free service. The Platform is not liable for losses caused by scheduled maintenance, third-party outages, telecom network failures or force majeure, though maintenance windows are announced in advance where possible and multi-channel failover is used in good faith."},{t:"h2",v:"6. Fair use"},{t:"p",v:"Resources are provisioned per tier. Sustained abusive patterns (continuous max-rate stress, sharing keys with third-party clusters, etc.) may be addressed through outreach, throttling or suspension — see the Acceptable Use Policy."},{t:"h2",v:"7. Intellectual property"},{t:"li",v:"The Platform software, interface, documentation and trademarks are owned by the Platform operator; this agreement grants only the rights necessary to use the service."},{t:"li",v:"Data you manage through the Platform (contacts, templates, send records and receipt metadata) belongs to you; the Platform processes it solely to provide the service."},{t:"h2",v:"8. Disclaimers & limitation of liability"},{t:"li",v:'The Platform is provided "as is". For outages or delays caused by provider failures, telecom networks or force majeure, the Platform is not liable, though multi-channel failover is used in good faith to mitigate.'},{t:"li",v:"To the maximum extent permitted by law, the Platform is not liable for any indirect losses, lost profits, goodwill or data losses."},{t:"li",v:"The Platform's aggregate liability is capped at the subscription fees you paid in the last 12 months."},{t:"h2",v:"9. Termination"},{t:"li",v:"You may cancel anytime and review your own data in the console. For material breach of these Terms or the Acceptable Use Policy, the Platform may suspend or terminate the service after notice."},{t:"li",v:"Non-payment: failed payments enter a 7-day grace period; accounts that remain unpaid are downgraded to Free (data is not deleted)."},{t:"li",v:"After termination: encrypted credentials and subscription records are deleted with the account; SMS metadata is retained for 30 days so you can review and back it up (contact support@mail.whaleal.com for a full export), then purged."},{t:"li",v:"Click details are kept 30 days on Free, 90 on Growth, 180 on Pro and 365 on Ultra. The lifetime click total stays. SMS logs store metadata only (no message body) and can be reviewed and exported as CSV in the console."},{t:"h2",v:"10. Changes to these terms"},{t:"p",v:"Material changes will be notified 30 days in advance via email or console. Continued use after the effective date constitutes acceptance of the revised terms; if you do not accept, you may stop using the Platform and contact support@mail.whaleal.com to retrieve your data."},{t:"h2",v:"11. Governing law & disputes"},{t:"p",v:"These terms are governed by the law of the Platform operator's place of registration. Disputes shall first be resolved amicably; failing that, they shall be submitted to the competent arbitration/court at the operator's location."}]},privacy:{title:"Privacy Policy",meta:{updated:"Last updated: 2026-09-28",effective:"Effective: 2026-09-28"},blocks:[{t:"p",v:"This policy explains what we collect, why, how it is protected, and your rights. In one line: we store metadata, never message bodies; keys are encrypted and always yours."},{t:"h2",v:"1. What we collect"},{t:"li",v:"Account data: your identity from Whaleal IDP sign-in (tenant ID) and email. We never store passwords — login is handled by enterprise identity services."},{t:"li",v:"SMS metadata: recipient numbers, status, timestamps, provider error codes, channel and rate details. Message bodies are never stored."},{t:"li",v:"Provider credentials: the API keys you bind, encrypted with AES-256-GCM; the console only ever shows a masked value."},{t:"li",v:"Subscription data: processed by Stripe. We never touch or store card details."},{t:"h2",v:"2. How we use it"},{t:"li",v:"Routing, receipt write-back, usage analytics and plan quota enforcement."},{t:"li",v:"Security protection and abuse prevention."},{t:"li",v:"We never sell your data, never use it for advertising, and never use it to train models."},{t:"h2",v:"3. Sharing"},{t:"li",v:"Sending necessarily goes through the providers you chose (Twilio/Vonage/Infobip etc.); their privacy policies apply to that leg."},{t:"li",v:"Payments are processed by Stripe; identity by Whaleal IDP. Website analytics on the public pages use Google Analytics, and only after you accept the cookie notice; beyond these, no disclosure to third parties without your consent."},{t:"li",v:"Under the EU/UK GDPR: you are the data controller for personal data you process; the Platform acts only as a data processor handling SMS metadata on your instructions. A Data Processing Agreement (DPA) is available on request via support@mail.whaleal.com."},{t:"h2",v:"4. Retention & deletion"},{t:"li",v:"Click details are kept 30 days on Free, 90 on Growth, 180 on Pro and 365 on Ultra. The lifetime click total stays. SMS logs store metadata only (no message body) and can be reviewed and exported as CSV in the console."},{t:"li",v:"Deleting your account removes encrypted credentials and subscription records; backup residue clears within the backup rotation window (≤30 days)."},{t:"h2",v:"5. Your rights"},{t:"p",v:"Retrieval, deletion, correction and consent withdrawal are available anytime via support@mail.whaleal.com."}]},aup:{title:"Acceptable Use Policy",meta:{updated:"Last updated: 2026-09-28",effective:"Effective: 2026-09-28"},blocks:[{t:"p",v:"This policy sets the boundaries for sending via the Platform. Violations may lead to throttling, suspension and regulatory cooperation obligations."},{t:"h2",v:"1. Prohibited content"},{t:"li",v:"Anything illegal in the recipient's jurisdiction, including fraud, phishing and malware distribution."},{t:"li",v:"Unsolicited bulk messaging; forged or circumvented opt-out mechanisms."},{t:"li",v:"Adult, violent-extremist or hateful content, and anything major providers prohibit."},{t:"li",v:"Content prohibited under applicable Chinese law."},{t:"h2",v:"2. Prohibited behaviors"},{t:"li",v:"Number-laundering, bulk number-probing and similar gray-market activity."},{t:"li",v:"Technical evasion of rate limits and quotas (multi-account workarounds, scripted stress flooding)."},{t:"li",v:"Reselling or lending the Platform or your keys to third parties for bulk sending."},{t:"h2",v:"3. Sender obligations"},{t:"li",v:"Comply with SMS regulations of each destination (e.g. US TCPA/A2P 10DLC registration, EU GDPR, local opt-out rules)."},{t:"li",v:"Provider-side reviews (templates, sender IDs, numbers) are completed by you in the provider portal."},{t:"h2",v:"4. Enforcement"},{t:"p",v:"By severity: notice → throttling → sending suspension → account termination. Unlawful use will be handled with regulators and law enforcement as required."},{t:"h2",v:"5. Reporting"},{t:"p",v:"Report violations to abuse@whaleal.com — we review and act promptly."}]}},zh:{terms:{title:"服务协议",meta:{updated:"最后更新：2026-09-28",effective:"生效日期：2026-09-28"},blocks:[{t:"p",v:"本协议是您与 Whaleal Platform（下称「平台」）之间关于使用平台服务的关键约定。注册或使用即表示您已阅读并同意本协议。"},{t:"h2",v:"1. 服务定位"},{t:"li",v:"平台是一款自带密钥（BYOL）多渠道短信中转工具：您自带短信供应商（CPaaS）账户与密钥，平台提供密钥托管、路由调度、回执处理与数据看板。"},{t:"li",v:"平台不售卖短信、不转售渠道、不加价、不经手任何短信费用。短信费用始终发生在您自己的供应商账户内。"},{t:"li",v:"平台不改变底层发送链路：消息按你指定的渠道原样转发。因你自有供应商账号状态（欠费、被封、限流等）导致的发送失败，平台不承担责任。"},{t:"li",v:"平台不承诺短信送达率。送达由渠道质量与供应商服务决定；平台如实呈现各渠道回执数据。"},{t:"h2",v:"2. 账户与密钥安全"},{t:"li",v:"您负责妥善保管平台账号、API 密钥及所绑定的供应商凭据，并对该等凭据项下发生的一切活动负责。"},{t:"li",v:"因凭据泄露、转借或保管不当导致的损失（包括由此产生的供应商侧费用），由您自行承担。发现泄露请立即在控制台轮换密钥。"},{t:"li",v:"供应商凭据采用 AES-256 加密存储，加密密钥与数据分离管理，仅在发送时于内存中解密，不写入磁盘或日志。"},{t:"h2",v:"3. 您的发送责任"},{t:"li",v:"您保证发送名单来源合法、已获得必要的发送同意，并对通过平台发送的内容及其合法性负全责，包括退订机制与目的地国家/地区电信法规遵从。"},{t:"li",v:"因您未遵守目的地国家/地区法规而产生的罚款、投诉或法律责任，由您自行承担。"},{t:"li",v:"您保证所绑定的供应商密钥来源合法，且已获供应商授权使用。"},{t:"li",v:"模板、签名等需要报备审核的事项，由您自行在供应商后台完成；平台不提供代审核服务。"},{t:"li",v:"平台在收到举报、执法请求或发现明显违法内容时，有权暂停或终止相关账户的发送权限，并依法配合调查。"},{t:"h2",v:"4. 订阅与计费"},{t:"li",v:"订阅经 Stripe Checkout 处理，支持月付/年付，按所选周期自动续费，直至取消。"},{t:"li",v:"您可随时在控制台「套餐与计费」页取消订阅；取消在当前计费周期结束时生效，周期内功能不受影响。"},{t:"li",v:"已支付的订阅费不予退款（法律另有强制规定的除外）。您可在付费前长期使用免费版充分评估，再决定是否升级。"},{t:"li",v:"扣款失败进入 7 天宽限期；宽限期满仍未成功支付的，账户降级为免费版。"},{t:"li",v:"渠道数量不限。每档都含每月短信段和短链点击。成长版及以上超出包含量后仍可继续，并按量收取平台费；还可使用批量短信和短链批量导入。运营商短信费在您自己的供应商账户结算。WhatsApp 与邮件含在套餐里。"},{t:"h2",v:"5. 服务可用性"},{t:"p",v:"平台不保证服务 100% 不间断或无错误。因计划维护、第三方服务中断、电信网络故障或不可抗力导致的服务暂停，平台不承担由此造成的损失，但将尽力提前公告维护窗口，并通过多渠道容灾降低影响。"},{t:"h2",v:"6. 公平使用"},{t:"p",v:"平台资源按套餐档位供给。持续异常的滥用行为（如无间隙满速压测、共享密钥给第三方集群滥用等）平台有权沟通、限速直至停服，详见《可接受使用政策》。"},{t:"h2",v:"7. 知识产权"},{t:"li",v:"平台软件、界面、文档与商标的知识产权归平台运营方所有；本协议仅授予您为使用服务所必需的权利。"},{t:"li",v:"您通过平台管理的数据（联系人、模板、发送记录与回执元数据）归您所有；平台仅为向您提供服务之目的处理该等数据。"},{t:"h2",v:"8. 免责与责任限制"},{t:"li",v:"平台按「现状」提供服务。对因供应商故障、电信网络问题、不可抗力导致的发送中断或延迟，平台不承担责任，但将尽力通过多渠道容灾降低影响。"},{t:"li",v:"在法律允许的最大范围内，平台不对任何间接损失、利润损失、商誉损失或数据损失承担责任。"},{t:"li",v:"平台的累计赔偿责任以您在最近 12 个月内已支付的订阅费为上限。"},{t:"h2",v:"9. 终止"},{t:"li",v:"您可随时取消订阅，并在控制台查阅自己的数据。您严重违反本协议或《可接受使用政策》的，平台有权经通知后暂停或终止服务。"},{t:"li",v:"未付款的处理：扣款失败进入 7 天宽限期，期满仍未支付的账户自动降级为免费版（而非直接删除数据）。"},{t:"li",v:"终止后数据处理：加密凭据与订阅记录随账户删除；短信元数据自终止起保留 30 天，供您查阅与备份（如需完整导出请联系 support@mail.whaleal.com），期满清除。"},{t:"li",v:"点击明细按套餐保留：免费 30 天、成长 90 天、专业 180 天、旗舰 365 天。累计点击数一直保留。短信日志只存元数据、不存正文，可在控制台查阅并导出 CSV。"},{t:"h2",v:"10. 协议变更"},{t:"p",v:"重大变更将提前 30 天通过邮件或控制台通知。变更生效后您继续使用平台，即视为接受修订后的协议；不接受的可停止使用，并可联系 support@mail.whaleal.com 取回数据。"},{t:"h2",v:"11. 争议解决"},{t:"p",v:"本协议适用平台运营主体注册地法律。因本协议产生的争议，双方应先友好协商；协商不成的，提交平台运营主体所在地有管辖权的仲裁/司法机构解决。"}]},privacy:{title:"隐私政策",meta:{updated:"最后更新：2026-09-28",effective:"生效日期：2026-09-28"},blocks:[{t:"p",v:"本政策说明平台收集哪些数据、为什么收集、如何保护，以及你的权利。核心一句话：我们存元数据，不存短信正文；密钥加密托管，且永远是你的。"},{t:"h2",v:"1. 我们收集什么"},{t:"li",v:"账户数据：经 Whaleal IDP 登录产生的身份标识（租户 ID）、邮箱。平台不存储密码，登录由企业统一身份服务完成。"},{t:"li",v:"短信元数据：收件号码、发送状态、时间戳、供应商错误码、渠道与费率信息。不存储短信正文内容。"},{t:"li",v:"供应商凭据：你绑定的 API 密钥，经 AES-256-GCM 加密后存储，控制台仅回显打码值。"},{t:"li",v:"订阅数据：经 Stripe 处理的订阅状态。平台不接触也不存储银行卡信息。"},{t:"h2",v:"2. 我们如何使用"},{t:"li",v:"路由调度、回执回写、用量统计与套餐配额计算。"},{t:"li",v:"安全防护与滥用检测。"},{t:"li",v:"不会将你的数据出售或用于广告，不会用于训练任何模型。"},{t:"h2",v:"3. 数据共享"},{t:"li",v:"短信发送必然经由你指定的供应商（Twilio/Vonage/Infobip 等），其各自隐私政策适用于该环节。"},{t:"li",v:"支付由 Stripe 处理；身份由 Whaleal IDP 处理。公开页面的访问统计使用 Google Analytics，且仅在你接受 Cookie 提示后才生效。除此之外未经你的同意不向第三方披露。"},{t:"li",v:"就欧盟/英国 GDPR 而言：你对自己处理的个人数据是数据控制者，平台仅作为数据处理者按你的指示处理短信元数据；如需签署数据处理协议（DPA），请联系 support@mail.whaleal.com。"},{t:"h2",v:"4. 数据保留与删除"},{t:"li",v:"点击明细按套餐保留：免费 30 天、成长 90 天、专业 180 天、旗舰 365 天。累计点击数一直保留。短信日志只存元数据、不存正文，可在控制台查阅并导出 CSV。"},{t:"li",v:"你删除账户时，加密凭据与订阅记录一并删除；备份中的残留数据在备份轮转期内（≤30 天）清除。"},{t:"h2",v:"5. 你的权利"},{t:"p",v:"你可以随时要求取回或删除数据、更正信息、撤销同意。行使权利请联系 support@mail.whaleal.com。"}]},aup:{title:"可接受使用政策",meta:{updated:"最后更新：2026-09-28",effective:"生效日期：2026-09-28"},blocks:[{t:"p",v:"本政策约定通过平台发送短信的边界。违反可能导致限速、停服与配合监管义务。"},{t:"h2",v:"1. 禁止内容"},{t:"li",v:"违反收件人所在地法律的任何内容，包括诈骗、钓鱼、恶意软件分发。"},{t:"li",v:"未经同意的批量骚扰短信；伪造或规避退订机制。"},{t:"li",v:"色情、暴力恐怖、仇恨言论及其他被主流供应商禁止的内容。"},{t:"li",v:"中国法律禁止的违法有害信息。"},{t:"h2",v:"2. 禁止行为"},{t:"li",v:"号码池清洗、批量探测有效号码等灰产行为。"},{t:"li",v:"绕开平台限速与配额的技术手段（多账号规避、脚本并发压测等）。"},{t:"li",v:"将平台或密钥转售、转借给第三方用于大规模发送。"},{t:"h2",v:"3. 发送者的法定义务"},{t:"li",v:"遵守目的地国家/地区的短信法规（如美国 TCPA/A2P 10DLC 注册、欧盟 GDPR、各地退订要求）。"},{t:"li",v:"需要供应商侧报备审核的模板、签名、发信号码，由你在供应商后台完成。"},{t:"h2",v:"4. 违规处理"},{t:"p",v:"按严重程度：提醒整改 → 限速 → 暂停发送 → 终止账户。涉及违法的，平台将依法配合监管与执法。"},{t:"h2",v:"5. 举报"},{t:"p",v:"发现违规内容请举报至 abuse@whaleal.com，我们会及时核查处理。"}]}},de:{terms:{title:"Nutzungsbedingungen",meta:{updated:"Zuletzt aktualisiert: 2026-09-28",effective:"Gültig ab: 2026-09-28"},blocks:[{t:"p",v:"Diese Vereinbarung regelt Ihre Nutzung von Whaleal Platform („Plattform“). Die Registrierung oder Nutzung der Plattform bedeutet, dass Sie diese gelesen und akzeptiert haben."},{t:"h2",v:"1. Was die Plattform ist"},{t:"li",v:"Die Plattform ist ein Multi-Kanal-SMS-Relay nach dem Bring-your-own-keys-Prinzip (BYOL): Sie stellen eigene CPaaS-Konten und Schlüssel bereit; die Plattform übernimmt Schlüsselverwahrung, Routing, Empfangsbestätigungen und Analysen."},{t:"li",v:"Die Plattform verkauft keine SMS und schlägt keine Carrier-Raten auf. Carrier-Gebühren bleiben in Ihrem eigenen Anbieter-Konto. Ein Paid-Plan kann zusätzlich eine Plattformgebühr für Nutzung über dem enthaltenen Kontingent erheben (Abschnitt 4)."},{t:"li",v:"Die Plattform verändert den zugrunde liegenden Versandweg nie: Nachrichten werden unverändert über den von Ihnen festgelegten Kanal weitergeleitet. Die Plattform haftet nicht für Versandfehler, die durch den Zustand Ihrer eigenen Provider-Konten verursacht werden (Rückstände, Sperrung, Drosselung)."},{t:"li",v:"Die Plattform garantiert keine Zustellraten. Die Zustellung hängt von Kanal- und Anbieterqualität ab; die Plattform stellt Empfangsdaten getreu dar."},{t:"h2",v:"2. Konto- und Schlüsselsicherheit"},{t:"li",v:"Sie sind verantwortlich für die Sicherung Ihres Plattform-Kontos, Ihrer API-Keys und gebundener Anbieter-Zugangsdaten sowie für alle Aktivitäten darunter."},{t:"li",v:"Verluste durch Zugangsdaten-Leak, -Verleih oder fahrlässige Verwahrung (einschließlich daraus entstehender Anbietergebühren) tragen Sie. Bei Entdeckung rotieren Sie die Keys sofort in der Konsole."},{t:"li",v:"Anbieter-Zugangsdaten werden mit AES-256 verschlüsselt gespeichert; die VerschlüsselungsKeys werden getrennt von den Daten verwaltet, nur im Speicher beim Versand entschlüsselt und nie auf Platte oder in Logs geschrieben."},{t:"h2",v:"3. Ihre Versandpflichten"},{t:"li",v:"Sie sichern zu, dass Ihre Versandlisten rechtmäßig beschafft sind und alle erforderlichen Einwilligungen vorliegen, und Sie tragen die alleinige Verantwortung für den Inhalt Ihrer Nachrichten und dessen Rechtmäßigkeit, einschließlich Opt-out-Behandlung und Telekom-Compliance jedes Zielorts."},{t:"li",v:"Bußgelder, Beschwerden oder rechtliche Haftung aus der Nichteinhaltung der Vorschriften des Ziellands tragen Sie."},{t:"li",v:"Sie sichern zu, dass alle gebundenen Anbieter-Keys rechtmäßig erlangt und vom Anbieter zur Nutzung autorisiert sind."},{t:"li",v:"Registrierungen, die eine anbieterseitige Prüfung erfordern (Vorlagen, Sender-IDs), führen Sie im Anbieterportal selbst durch; die Plattform reicht nichts in Ihrem Namen ein."},{t:"li",v:"Bei Beschwerden, Anfragen von Strafverfolgungsbehörden oder eindeutig rechtswidrigen Inhalten kann die Plattform die Versandfähigkeit des betroffenen Kontos aussetzen oder beenden und bei Ermittlungen gesetzeskonform kooperieren."},{t:"h2",v:"4. Abonnement und Abrechnung"},{t:"li",v:"Abos werden über Stripe Checkout verarbeitet, monatlich oder jährlich, und verlängern sich automatisch in jedem Zyklus bis zur Kündigung."},{t:"li",v:"Sie können jederzeit unter Tarife & Abrechnung in der Konsole kündigen; die Kündigung wirkt zum Ende des aktuellen Zyklus, mit vollem Zugang bis dahin."},{t:"li",v:"Bezahlte Abo-Gebühren sind nicht erstattungsfähig (sofern zwingendes Recht nichts anderes verlangt). Der Free-Tarif ist unbegrenzt verfügbar, damit Sie vor dem Upgrade testen können."},{t:"li",v:"Fehlgeschlagene Zahlungen lösen eine 7-tägige Kulanzfrist aus; danach wird das Konto auf Free herabgestuft."},{t:"li",v:"Verbindungen sind unbegrenzt. Jeder Tarif enthält monatliche SMS-Segmente und Kurzlink-Klicks. Growth und höher laufen über dieses Kontingent hinaus, zahlen eine Plattformgebühr für die zusätzliche Nutzung und beinhalten Bulk-SMS sowie Kurzlink-Import. Die Carrier-SMS-Gebühren bleiben in Ihrem eigenen Anbieter-Konto. WhatsApp und E-Mail sind enthalten."},{t:"h2",v:"5. Verfügbarkeit des Dienstes"},{t:"p",v:"Die Plattform garantiert keinen ununterbrochenen oder fehlerfreien Betrieb. Die Plattform haftet nicht für Verluste, die durch geplante Wartung, Ausfälle Dritter, Ausfälle der Telekommunikationsnetze oder höhere Gewalt entstehen; Wartungsfenster werden nach Möglichkeit rechtzeitig angekündigt und ein Multi-Channel-Failover wird nach bestem Wissen und Gewissen eingesetzt."},{t:"h2",v:"6. Fair Use"},{t:"p",v:"Ressourcen werden je nach Tarifstufe bereitgestellt. Anhaltend missbräuchliche Muster (dauerhafte Höchstraten-Belastung, Weitergabe von Schlüsseln an Cluster Dritter usw.) können durch Kontaktaufnahme, Drosselung oder Sperrung geahndet werden – siehe die Acceptable Use Policy."},{t:"h2",v:"7. Geistiges Eigentum"},{t:"li",v:"Die Plattform-Software, Oberfläche, Dokumentation und Marken gehören dem Plattformbetreiber; diese Vereinbarung gewährt nur die zur Nutzung des Dienstes erforderlichen Rechte."},{t:"li",v:"Daten, die Sie über die Plattform verwalten (Kontakte, Vorlagen, Versandaufzeichnungen und Empfangs-Metadaten), gehören Ihnen; die Plattform verarbeitet sie ausschließlich zur Erbringung des Dienstes."},{t:"h2",v:"8. Haftungsausschlüsse und Haftungsbeschränkung"},{t:"li",v:"Die Plattform wird „wie besehen“ bereitgestellt. Für Ausfälle oder Verzögerungen aufgrund von Anbieterausfällen, Telekomnetzen oder höherer Gewalt haftet die Plattform nicht; es wird jedoch nach gutem Glauben ein Multi-Channel-Failover zur Schadensminderung eingesetzt."},{t:"li",v:"Im gesetzlich maximal zulässigen Umfang haftet die Plattform nicht für indirekte Verluste, entgangenen Gewinn, Goodwill oder Datenverluste."},{t:"li",v:"Die Gesamthaftung der Plattform ist auf die Abonnementgebühren begrenzt, die Sie in den letzten 12 Monaten gezahlt haben."},{t:"h2",v:"9. Kündigung"},{t:"li",v:"Sie können jederzeit kündigen und Ihre eigenen Daten in der Konsole prüfen. Bei wesentlichem Verstoß gegen diese Bedingungen oder die Richtlinie für akzeptable Nutzung kann die Plattform den Dienst nach Benachrichtigung aussetzen oder beenden."},{t:"li",v:"Zahlungsverzug: fehlgeschlagene Zahlungen unterliegen einer 7-tägigen Karenzfrist; Konten, die weiterhin unbezahlt bleiben, werden auf Free herabgestuft (Daten werden nicht gelöscht)."},{t:"li",v:"Nach der Kündigung: verschlüsselte Zugangsdaten und Abonnement-Daten werden mit dem Konto gelöscht; SMS-Metadaten werden 30 Tage aufbewahrt, damit Sie sie prüfen und sichern können (für einen vollständigen Export wenden Sie sich an support@mail.whaleal.com), und anschließend entfernt."},{t:"li",v:"Klickdetails werden 30 Tage bei Free, 90 bei Growth, 180 bei Pro und 365 bei Ultra aufbewahrt. Die Gesamtklickzahl über die gesamte Laufzeit bleibt erhalten. SMS-Logs speichern nur Metadaten (kein Nachrichtentext) und können in der Konsole geprüft und als CSV exportiert werden."},{t:"h2",v:"10. Änderungen dieser Bedingungen"},{t:"p",v:"Wesentliche Änderungen werden 30 Tage im Voraus per E-Mail oder Konsole angekündigt. Die weitere Nutzung nach Inkrafttreten gilt als Annahme der geänderten Bedingungen; wenn Sie nicht zustimmen, können Sie die Nutzung einstellen und support@mail.whaleal.com kontaktieren, um Ihre Daten abzurufen."},{t:"h2",v:"11. Anwendbares Recht und Streitbeilegung"},{t:"p",v:"Diese Bedingungen unterliegen dem Recht des Registrierungsortes des Plattformbetreibers. Streitigkeiten sind zunächst gütlich beizulegen; andernfalls sind sie dem zuständigen Schiedsgericht bzw. Gericht am Sitz des Betreibers vorzulegen."}]},privacy:{title:"Datenschutzerklärung",meta:{updated:"Zuletzt aktualisiert: 2026-09-28",effective:"Gültig ab: 2026-09-28"},blocks:[{t:"p",v:"Diese Richtlinie erklärt, was wir erheben, warum, wie es geschützt wird und welche Rechte Sie haben. Kurz gesagt: Wir speichern Metadaten, niemals Nachrichteninhalte; Schlüssel sind verschlüsselt und gehören stets Ihnen."},{t:"h2",v:"1. Was wir erheben"},{t:"li",v:"Kontodaten: Ihre Identität aus der Whaleal-IDP-Anmeldung (Tenant-ID) und E-Mail-Adresse. Wir speichern niemals Passwörter — die Anmeldung erfolgt über Enterprise-Identitätsdienste."},{t:"li",v:"SMS-Metadaten: Empfängernummern, Status, Zeitstempel, Provider-Fehlercodes, Kanal- und Tarifdetails. Nachrichteninhalte werden nie gespeichert."},{t:"li",v:"Provider-Zugangsdaten: die von Ihnen gebundenen API-Schlüssel, verschlüsselt mit AES-256-GCM; die Konsole zeigt ausschließlich einen maskierten Wert an."},{t:"li",v:"Abonnement-Daten: verarbeitet von Stripe. Wir berühren oder speichern niemals Kartendaten."},{t:"h2",v:"2. Wie wir sie verwenden"},{t:"li",v:"Routing, Empfangs-Rückschreibung, Nutzungsanalyse und Durchsetzung von Tarifkontingenten."},{t:"li",v:"Sicherheitsschutz und Missbrauchsprävention."},{t:"li",v:"Wir verkaufen Ihre Daten nie, nutzen sie nie für Werbung und nie zum Trainieren von Modellen."},{t:"h2",v:"3. Weitergabe"},{t:"li",v:"Der Versand läuft notwendigerweise über die von Ihnen gewählten Provider (Twilio/Vonage/Infobip usw.); deren Datenschutzrichtlinien gelten für diesen Abschnitt."},{t:"li",v:"Zahlungen werden von Stripe verarbeitet, die Identität von Whaleal IDP. Website-Analysen auf den öffentlichen Seiten nutzen Google Analytics, und nur nachdem Sie den Cookie-Hinweis akzeptiert haben; darüber hinaus geben wir ohne Ihre Zustimmung nichts an Dritte weiter."},{t:"li",v:"Nach der EU/UK-DSGVO: Sie sind der Verantwortliche für die personenbezogenen Daten, die Sie verarbeiten; die Plattform fungiert ausschließlich als Auftragsverarbeiter, der SMS-Metadaten nach Ihren Weisungen verarbeitet. Eine Datenverarbeitungsvereinbarung (DPA) ist auf Anfrage über support@mail.whaleal.com erhältlich."},{t:"h2",v:"4. Aufbewahrung und Löschung"},{t:"li",v:"Klickdetails werden 30 Tage bei Free, 90 bei Growth, 180 bei Pro und 365 bei Ultra aufbewahrt. Die Gesamtklickzahl über die gesamte Laufzeit bleibt erhalten. SMS-Logs speichern nur Metadaten (kein Nachrichtentext) und können in der Konsole geprüft und als CSV exportiert werden."},{t:"li",v:"Das Löschen Ihres Kontos entfernt verschlüsselte Zugangsdaten und Abo-Datensätze; Reste in Backups werden innerhalb der Backup-Rotationsfrist (≤30 Tage) gelöscht."},{t:"h2",v:"5. Ihre Rechte"},{t:"p",v:"Abruf, Löschung, Berichtigung und Widerruf der Einwilligung sind jederzeit über support@mail.whaleal.com möglich."}]},aup:{title:"Richtlinie für akzeptable Nutzung",meta:{updated:"Zuletzt aktualisiert: 2026-09-28",effective:"Gültig ab: 2026-09-28"},blocks:[{t:"p",v:"Diese Richtlinie legt die Grenzen für den Versand über die Plattform fest. Verstöße können zu Drosselung, Sperrung und Verpflichtungen zur Zusammenarbeit mit Aufsichtsbehörden führen."},{t:"h2",v:"1. Verbotene Inhalte"},{t:"li",v:"Alles, was am Ort des Empfängers rechtswidrig ist, einschließlich Betrug, Phishing und Verbreitung von Schadsoftware."},{t:"li",v:"Unerbetene Massennachrichten; gefälschte oder umgangene Opt-out-Mechanismen."},{t:"li",v:"Inhalte mit Erwachsenenthemen, gewalt-extremistische oder hasserfüllte Inhalte und alles, was große Anbieter verbieten."},{t:"li",v:"Inhalte, die nach geltendem chinesischem Recht verboten sind."},{t:"h2",v:"2. Verbotene Verhaltensweisen"},{t:"li",v:"Nummernwäsche, massenhaftes Nummern-Scannen und ähnliche Graumarkt-Aktivitäten."},{t:"li",v:"Technische Umgehung von Ratenlimits und Kontingenten (Workarounds mit mehreren Konten, skriptgesteuerte Stress-Überflutung)."},{t:"li",v:"Weiterverkauf oder Verleih der Plattform oder Ihrer Keys an Dritte für Massenversand."},{t:"h2",v:"3. Pflichten des Absenders"},{t:"li",v:"Beachten Sie die SMS-Vorschriften jedes Zielgebiets (z. B. US-TCPA/A2P-10DLC-Registrierung, EU-DSGVO, lokale Opt-out-Regeln)."},{t:"li",v:"Anbieterseitige Prüfungen (Vorlagen, Sender-IDs, Nummern) führen Sie im Anbieterportal selbst durch."},{t:"h2",v:"4. Durchsetzung"},{t:"p",v:"Nach Schweregrad: Hinweis → Drosselung → Versandstopp → Kontosperrung. Rechtswidrige Nutzung wird nach Bedarf mit Aufsichtsbehörden und Strafverfolgungsbehörden geahndet."},{t:"h2",v:"5. Meldung"},{t:"p",v:"Verstöße melden Sie bitte an abuse@whaleal.com — wir prüfen und handeln umgehend."}]}},fr:{terms:{title:"Conditions d'utilisation",meta:{updated:"Dernière mise à jour : 2026-09-28",effective:"En vigueur le : 2026-09-28"},blocks:[{t:"p",v:"Le présent accord régit votre utilisation de Whaleal Platform (la « Plateforme »). Vous inscrire ou utiliser la Plateforme signifie que vous l’avez lu et accepté."},{t:"h2",v:"1. Ce qu'est la plateforme"},{t:"li",v:"La plateforme est un relais SMS multicanal « apportez vos propres clés » (BYOL) : vous fournissez vos propres comptes et clés CPaaS ; la plateforme assure la conservation des clés, le routage, la gestion des accusés de réception et les analyses."},{t:"li",v:"La Plateforme ne revend pas de SMS et n'augmente pas les tarifs de l'opérateur. Les frais de l'opérateur restent sur votre propre compte fournisseur. Une offre payante peut également entraîner des frais de plateforme pour l'usage au-delà du quota inclus (section 4)."},{t:"li",v:"La plateforme ne modifie jamais le chemin d'envoi sous-jacent : les messages sont transmis tels quels via le canal que vous désignez. La plateforme n'est pas responsable des échecs d'envoi causés par l'état de vos propres comptes fournisseurs (impayés, suspension, limitation de débit)."},{t:"li",v:"La Plateforme ne garantit pas les taux de livraison. La livraison dépend de la qualité du canal et du fournisseur ; la Plateforme présente fidèlement les données d'accusé de réception."},{t:"h2",v:"2. Sécurité du compte et des clés"},{t:"li",v:"Vous êtes responsable de la protection de votre compte Plateforme, de vos clés API et des identifiants fournisseur liés, ainsi que de toute activité menée sous ceux-ci."},{t:"li",v:"Les pertes dues à la fuite, au prêt ou à la garde négligente des identifiants (y compris les frais fournisseur qui en découlent) sont à votre charge. En cas de découverte, changez immédiatement les clés dans la console."},{t:"li",v:"Les identifiants fournisseur sont stockés chiffrés avec AES-256 ; les clés de chiffrement sont gérées séparément des données, déchiffrées uniquement en mémoire au moment de l'envoi, et jamais écrites sur disque ni dans les journaux."},{t:"h2",v:"3. Vos responsabilités d'envoi"},{t:"li",v:"Vous garantissez que vos listes d'envoi proviennent de sources légales avec tous les consentements nécessaires, et vous êtes seul responsable du contenu envoyé et de sa légalité, y compris la gestion des désabonnements et la conformité télécom de chaque destination."},{t:"li",v:"Les amendes, réclamations ou responsabilités légales découlant de votre non-conformité aux réglementations du pays de destination sont à votre charge."},{t:"li",v:"Vous garantissez que toutes les clés fournisseur que vous liez ont été obtenues légalement et sont autorisées à l'usage par le fournisseur."},{t:"li",v:"Les enregistrements nécessitant une validation côté fournisseur (modèles, identifiants d'expéditeur) sont effectués par vous dans le portail du fournisseur ; la Plateforme ne les dépose pas à votre place."},{t:"li",v:"En cas de réclamations, de demandes des autorités ou de contenu manifestement illégal, la Plateforme peut suspendre ou résilier la capacité d'envoi du compte concerné et coopérer aux enquêtes comme l'exige la loi."},{t:"h2",v:"4. Abonnement et facturation"},{t:"li",v:"Les abonnements sont traités via Stripe Checkout, mensuellement ou annuellement, et se renouvellent automatiquement à chaque cycle jusqu'à résiliation."},{t:"li",v:"Vous pouvez résilier à tout moment depuis Offres & Facturation dans la console ; la résiliation prend effet à la fin du cycle en cours, l'accès restant intact jusque-là."},{t:"li",v:"Les frais d'abonnement payants ne sont pas remboursables (sauf disposition légale impérative contraire). L'offre Free reste disponible indéfiniment pour vous permettre d'évaluer avant de passer à une offre supérieure."},{t:"li",v:"Un échec de paiement ouvre un délai de grâce de 7 jours ; passé ce délai, le compte repasse à Free."},{t:"li",v:"Les connexions sont illimitées. Chaque offre inclut des segments SMS et des clics sur liens courts chaque mois. Growth et les offres supérieures continuent au-delà de ce quota, paient des frais de plateforme pour l'usage supplémentaire et incluent l'import groupé de SMS et de liens courts. Les frais SMS de l'opérateur restent sur votre propre compte fournisseur. WhatsApp et l'e-mail sont inclus."},{t:"h2",v:"5. Disponibilité du service"},{t:"p",v:"La Platform ne garantit pas un service ininterrompu ni exempt d'erreurs. La Platform n'est pas responsable des pertes causées par une maintenance planifiée, des pannes de tiers, des défaillances des réseaux de télécommunication ou la force majeure, bien que les fenêtres de maintenance soient annoncées à l'avance dans la mesure du possible et qu'une bascule multicanal soit appliquée de bonne foi."},{t:"h2",v:"6. Usage équitable"},{t:"p",v:"Les ressources sont provisionnées selon le niveau de service. Les comportements abusifs soutenus (tests continus à débit maximal, partage de clés avec des clusters tiers, etc.) peuvent être traités par une prise de contact, une limitation de débit ou une suspension – consultez la Acceptable Use Policy."},{t:"h2",v:"7. Propriété intellectuelle"},{t:"li",v:"Le logiciel, l'interface, la documentation et les marques de la Plateforme appartiennent à l'exploitant de la Plateforme ; le présent contrat n'accorde que les droits nécessaires à l'utilisation du service."},{t:"li",v:"Les données que vous gérez via la Plateforme (contacts, modèles, journaux d'envoi et métadonnées d'accusés de réception) vous appartiennent ; la Plateforme ne les traite que pour fournir le service."},{t:"h2",v:"8. Avertissements et limitation de responsabilité"},{t:"li",v:"La Plateforme est fournie « en l’état ». Elle n’est pas responsable des interruptions ou retards dus à une défaillance du fournisseur, aux réseaux de télécommunication ou à un cas de force majeure ; une bascule multicanal est toutefois appliquée de bonne foi pour en limiter l’impact."},{t:"li",v:"Dans la mesure maximale permise par la loi, la Plateforme n'est pas responsable des pertes indirectes, manques à gagner, pertes de clientèle ou de données."},{t:"li",v:"La responsabilité globale de la Plateforme est plafonnée aux frais d'abonnement que vous avez payés au cours des 12 derniers mois."},{t:"h2",v:"9. Résiliation"},{t:"li",v:"Vous pouvez résilier à tout moment et consulter vos propres données dans la console. En cas de manquement grave aux présentes conditions ou à la Politique d'utilisation acceptable, la Plateforme peut suspendre ou résilier le service après notification."},{t:"li",v:"Non-paiement : les paiements échoués bénéficient d'un délai de grâce de 7 jours ; les comptes toujours impayés sont rétrogradés vers Free (les données ne sont pas supprimées)."},{t:"li",v:"Après résiliation : les identifiants chiffrés et les données d'abonnement sont supprimés avec le compte ; les métadonnées SMS sont conservées 30 jours pour vous permettre de les consulter et de les sauvegarder (contactez support@mail.whaleal.com pour un export complet), puis purgées."},{t:"li",v:"Les détails des clics sont conservés 30 jours sur Free, 90 sur Growth, 180 sur Pro et 365 sur Ultra. Le total cumulé des clics reste. Les journaux SMS ne stockent que les métadonnées (sans corps du message) et peuvent être consultés et exportés au format CSV dans la console."},{t:"h2",v:"10. Modifications des présentes conditions"},{t:"p",v:"Les modifications importantes sont notifiées 30 jours à l’avance par e-mail ou via la console. L’utilisation poursuivie après la date d’entrée en vigueur vaut acceptation des conditions révisées ; si vous ne les acceptez pas, vous pouvez cesser d’utiliser la Plateforme et contacter support@mail.whaleal.com pour récupérer vos données."},{t:"h2",v:"11. Droit applicable et litiges"},{t:"p",v:"Ces conditions sont régies par la loi du lieu d'immatriculation de l'exploitant de la Plateforme. Les litiges sont d'abord résolus à l'amiable ; à défaut, ils sont soumis à l'arbitrage ou au tribunal compétent du lieu de l'exploitant."}]},privacy:{title:"Politique de confidentialité",meta:{updated:"Dernière mise à jour : 2026-09-28",effective:"En vigueur le : 2026-09-28"},blocks:[{t:"p",v:"Cette politique explique ce que nous collectons, pourquoi, comment c'est protégé et quels sont vos droits. En une phrase : nous stockons des métadonnées, jamais le contenu des messages ; les clés sont chiffrées et vous appartiennent toujours."},{t:"h2",v:"1. Ce que nous collectons"},{t:"li",v:"Données de compte : votre identité issue de la connexion Whaleal IDP (ID de locataire) et votre e-mail. Nous ne stockons jamais de mots de passe — la connexion est gérée par des services d'identité d'entreprise."},{t:"li",v:"Métadonnées SMS : numéros de destinataires, statut, horodatages, codes d'erreur des fournisseurs, canal et détails de tarification. Les contenus des messages ne sont jamais stockés."},{t:"li",v:"Identifiants fournisseurs : les clés API que vous associez, chiffrées avec AES-256-GCM ; la console n'affiche qu'une valeur masquée."},{t:"li",v:"Données d'abonnement : traitées par Stripe. Nous ne touchons ni ne stockons jamais les données de carte."},{t:"h2",v:"2. Comment nous les utilisons"},{t:"li",v:"Routage, réécriture des accusés de réception, analytique d'usage et application des quotas d'offre."},{t:"li",v:"Protection de la sécurité et prévention des abus."},{t:"li",v:"Nous ne vendons jamais vos données, ne les utilisons jamais à des fins publicitaires et ne nous en servons jamais pour entraîner des modèles."},{t:"h2",v:"3. Partage"},{t:"li",v:"L'envoi passe nécessairement par les fournisseurs que vous avez choisis (Twilio/Vonage/Infobip, etc.) ; leurs politiques de confidentialité s'appliquent à cette étape."},{t:"li",v:"Les paiements sont traités par Stripe ; l'identité par Whaleal IDP. L'analytique du site sur les pages publiques utilise Google Analytics, et uniquement après acceptation de l'avis sur les cookies ; au-delà, aucune divulgation à des tiers sans votre consentement."},{t:"li",v:"Conformément au RGPD de l'UE/du Royaume-Uni : vous êtes le responsable du traitement des données personnelles que vous traitez ; la plateforme agit uniquement comme sous-traitant traitant les métadonnées SMS selon vos instructions. Une convention de traitement des données (DPA) est disponible sur demande via support@mail.whaleal.com."},{t:"h2",v:"4. Conservation et suppression"},{t:"li",v:"Les détails des clics sont conservés 30 jours sur Free, 90 sur Growth, 180 sur Pro et 365 sur Ultra. Le total cumulé des clics reste. Les journaux SMS ne stockent que les métadonnées (sans corps du message) et peuvent être consultés et exportés au format CSV dans la console."},{t:"li",v:"La suppression de votre compte efface les identifiants chiffrés et les enregistrements d'abonnement ; les résidus de sauvegarde disparaissent dans la fenêtre de rotation des sauvegardes (≤ 30 jours)."},{t:"h2",v:"5. Vos droits"},{t:"p",v:"La récupération, la suppression, la correction et le retrait du consentement sont disponibles à tout moment via support@mail.whaleal.com."}]},aup:{title:"Politique d'utilisation acceptable",meta:{updated:"Dernière mise à jour : 2026-09-28",effective:"En vigueur le : 2026-09-28"},blocks:[{t:"p",v:"Cette politique définit les limites d'envoi via la Platform. Les violations peuvent entraîner une limitation de débit, une suspension et des obligations de coopération avec les autorités de régulation."},{t:"h2",v:"1. Contenus interdits"},{t:"li",v:"Toute activité illégale dans la juridiction du destinataire, y compris la fraude, le phishing et la diffusion de logiciels malveillants."},{t:"li",v:"Envois massifs non sollicités ; mécanismes de désabonnement falsifiés ou contournés."},{t:"li",v:"Contenus pour adultes, extrémistes-violents ou haineux, et tout ce que les grands fournisseurs interdisent."},{t:"li",v:"Contenus interdits par le droit chinois applicable."},{t:"h2",v:"2. Comportements interdits"},{t:"li",v:"Blanchiment de numéros, sondage de numéros en masse et activités similaires du marché gris."},{t:"li",v:"Contournement technique des limites de débit et des quotas (astuces multi-comptes, inondation par scripts)."},{t:"li",v:"La revente ou le prêt de la Plateforme ou de vos clés à des tiers pour des envois en masse."},{t:"h2",v:"3. Obligations de l'expéditeur"},{t:"li",v:"Respectez la réglementation SMS de chaque destination (ex. : enregistrement A2P 10DLC du TCPA aux États-Unis, RGPD de l'UE, règles locales d'opt-out)."},{t:"li",v:"Les validations côté fournisseur (modèles, identifiants d'expéditeur, numéros) sont effectuées par vous dans le portail du fournisseur."},{t:"h2",v:"4. Application"},{t:"p",v:"Par gravité : avis → limitation de débit → suspension des envois → résiliation du compte. Les usages illicites seront traités avec les autorités de régulation et les forces de l'ordre le cas échéant."},{t:"h2",v:"5. Signalement"},{t:"p",v:"Signalez les violations à abuse@whaleal.com — nous examinons et agissons rapidement."}]}},es:{terms:{title:"Términos del Servicio",meta:{updated:"Última actualización: 2026-09-28",effective:"Vigente desde: 2026-09-28"},blocks:[{t:"p",v:"Este acuerdo rige su uso de Whaleal Platform (la «Plataforma»). Registrarse o utilizar la Plataforma significa que lo ha leído y aceptado."},{t:"h2",v:"1. Qué es la plataforma"},{t:"li",v:"La plataforma es un relé SMS multicanal de trae-tus-propias-claves (BYOL): tú aportas tus propias cuentas y claves CPaaS; la plataforma ofrece custodia de claves, enrutamiento, gestión de confirmaciones y analítica."},{t:"li",v:"La Plataforma no revende SMS ni aplica sobrecargo a las tarifas del operador. Los cargos del operador permanecen en su propia cuenta de proveedor. Un plan de pago también puede pagar una tarifa de plataforma por el uso que supere la cuota incluida (sección 4)."},{t:"li",v:"La plataforma nunca altera la ruta de envío subyacente: los mensajes se reenvían tal cual por el canal que designes. La plataforma no se hace responsable de los fallos de envío causados por el estado de tus propias cuentas de proveedor (impagos, suspensión, limitación de velocidad)."},{t:"li",v:"La Plataforma no garantiza tasas de entrega. La entrega depende de la calidad del canal y del proveedor; la Plataforma muestra los datos de confirmación con fidelidad."},{t:"h2",v:"2. Seguridad de cuenta y claves"},{t:"li",v:"Usted es responsable de proteger su cuenta de la Plataforma, sus claves API y las credenciales vinculadas, y de toda actividad realizada bajo ellas."},{t:"li",v:"Las pérdidas causadas por fuga, cesión o custodia negligente de credenciales (incluidos los cargos consiguientes del proveedor) corren por su cuenta. Al detectarlo, rote las claves de inmediato en la consola."},{t:"li",v:"Las credenciales del proveedor se almacenan cifradas con AES-256; las claves de cifrado se gestionan por separado de los datos, se descifran solo en memoria en el momento del envío y nunca se escriben en disco ni en registros."},{t:"h2",v:"3. Tus responsabilidades de envío"},{t:"li",v:"Usted garantiza que sus listas de envío tienen origen legal y todos los consentimientos necesarios, y responde en exclusiva por el contenido que envía y su legalidad, incluida la gestión de bajas y el cumplimiento telecomunicativo de cada destino."},{t:"li",v:"Las multas, reclamaciones o responsabilidades legales derivadas del incumplimiento de la normativa del país de destino corren por su cuenta."},{t:"li",v:"Usted garantiza que todas las claves de proveedor que vincula se han obtenido legalmente y están autorizadas para su uso por el proveedor."},{t:"li",v:"Los registros que requieren revisión del proveedor (plantillas, IDs de remitente) los realiza usted en el portal del proveedor; la Plataforma no los presenta en su nombre."},{t:"li",v:"Ante reclamaciones, requerimientos de las autoridades o contenido claramente ilícito, la Plataforma puede suspender o cerrar la capacidad de envío de la cuenta afectada y cooperar con las investigaciones según exija la ley."},{t:"h2",v:"4. Suscripción y facturación"},{t:"li",v:"Las suscripciones se procesan con Stripe Checkout, mensual o anualmente, y se renuevan automáticamente cada ciclo hasta su cancelación."},{t:"li",v:"Puede cancelar cuando quiera desde Planes y facturación en la consola; la cancelación surte efecto al final del ciclo actual y el acceso permanece intacto hasta entonces."},{t:"li",v:"Las tarifas de suscripción de pago no son reembolsables (salvo que la ley obligue lo contrario). El plan Free está disponible indefinidamente para que pueda evaluar antes de mejorar."},{t:"li",v:"Los pagos fallidos entran en un período de gracia de 7 días; después, la cuenta baja a Free."},{t:"li",v:"Las conexiones son ilimitadas. Cada plan incluye segmentos SMS y clics de enlaces cortos al mes. Growth y superiores siguen más allá de esa cuota, pagan una tarifa de plataforma por el uso adicional e incluyen importación masiva de SMS y de enlaces cortos. Los cargos de SMS del operador permanecen en su propia cuenta de proveedor. WhatsApp y email están incluidos."},{t:"h2",v:"5. Disponibilidad del servicio"},{t:"p",v:"La Plataforma no garantiza un servicio ininterrumpido ni libre de errores. La Plataforma no se hace responsable de las pérdidas causadas por mantenimiento programado, caídas de terceros, fallos de las redes de telecomunicaciones o fuerza mayor, aunque los periodos de mantenimiento se anuncian con antelación siempre que es posible y se aplica concienzudamente una conmutación por error multicanal."},{t:"h2",v:"6. Uso razonable"},{t:"p",v:"Los recursos se aprovisionan según el plan. Los patrones abusivos sostenidos (pruebas continuas a velocidad máxima, compartir claves con clústeres de terceros, etc.) pueden atenderse con avisos, limitación de velocidad o suspensión; consulta la Acceptable Use Policy."},{t:"h2",v:"7. Propiedad intelectual"},{t:"li",v:"El software, la interfaz, la documentación y las marcas de la Plataforma pertenecen al operador de la Plataforma; este acuerdo concede solo los derechos necesarios para usar el servicio."},{t:"li",v:"Los datos que gestiona a través de la Plataforma (contactos, plantillas, registros de envío y metadatos de confirmación) son suyos; la Plataforma los procesa únicamente para prestar el servicio."},{t:"h2",v:"8. Descargos y limitación de responsabilidad"},{t:"li",v:"La Plataforma se proporciona «tal cual». No se responsabiliza de las interrupciones o retrasos causados por fallos del proveedor, redes de telecomunicaciones o fuerza mayor; no obstante, se aplica de buena fe una conmutación por error multicanal para mitigar el impacto."},{t:"li",v:"En la máxima medida permitida por la ley, la Plataforma no responde por daños indirectos, pérdida de beneficios, reputación ni datos."},{t:"li",v:"La responsabilidad agregada de la Plataforma está limitada a las cuotas de suscripción que pagó en los últimos 12 meses."},{t:"h2",v:"9. Terminación"},{t:"li",v:"Puede cancelar en cualquier momento y revisar sus propios datos en la consola. Por incumplimiento grave de estos Términos o de la Política de Uso Aceptable, la Plataforma puede suspender o cerrar el servicio tras notificarlo."},{t:"li",v:"Impago: los pagos fallidos entran en un periodo de gracia de 7 días; las cuentas que sigan sin pagar se degradan a Free (no se eliminan los datos)."},{t:"li",v:"Tras la terminación: las credenciales cifradas y los registros de suscripción se eliminan con la cuenta; los metadatos SMS se conservan 30 días para que puedas revisarlos y respaldarlos (contacta con support@mail.whaleal.com para una exportación completa) y después se purgan."},{t:"li",v:"Los detalles de clics se conservan 30 días en Free, 90 en Growth, 180 en Pro y 365 en Ultra. El total acumulado de clics se mantiene. Los registros SMS guardan solo metadatos (sin cuerpo del mensaje) y se pueden revisar y exportar a CSV desde la consola."},{t:"h2",v:"10. Cambios en estos términos"},{t:"p",v:"Los cambios sustanciales se notifican con 30 días de antelación por correo electrónico o consola. El uso continuado tras la fecha de entrada en vigor supone la aceptación de las condiciones revisadas; si no las acepta, puede dejar de usar la Plataforma y contactar con support@mail.whaleal.com para recuperar sus datos."},{t:"h2",v:"11. Ley aplicable y disputas"},{t:"p",v:"Estos términos se rigen por la ley del lugar de registro del operador de la Plataforma. Las disputas se resolverán primero de forma amistosa; de no lograrse, se someterán al arbitraje o tribunal competente del lugar del operador."}]},privacy:{title:"Política de Privacidad",meta:{updated:"Última actualización: 2026-09-28",effective:"Vigente desde: 2026-09-28"},blocks:[{t:"p",v:"Esta política explica qué recopilamos, por qué, cómo se protege y cuáles son tus derechos. En una línea: almacenamos metadatos, nunca el contenido de los mensajes; las claves están cifradas y siempre son tuyas."},{t:"h2",v:"1. Qué recopilamos"},{t:"li",v:"Datos de cuenta: tu identidad del inicio de sesión con Whaleal IDP (ID de inquilino) y tu correo. Nunca guardamos contraseñas: el inicio de sesión lo gestionan servicios de identidad empresariales."},{t:"li",v:"Metadatos SMS: números de destinatario, estado, marcas de tiempo, códigos de error del proveedor, canal y detalles de tarifa. Nunca se guarda el contenido de los mensajes."},{t:"li",v:"Credenciales de proveedor: las claves API que vinculas, cifradas con AES-256-GCM; la consola solo muestra un valor enmascarado."},{t:"li",v:"Datos de suscripción: procesados por Stripe. Nunca tocamos ni guardamos datos de tarjeta."},{t:"h2",v:"2. Cómo los usamos"},{t:"li",v:"Enrutamiento, escritura de estados, analítica de uso y aplicación de cuotas del plan."},{t:"li",v:"Protección de seguridad y prevención de abusos."},{t:"li",v:"Nunca vendemos sus datos, nunca los usamos para publicidad y nunca los usamos para entrenar modelos."},{t:"h2",v:"3. Compartición"},{t:"li",v:"El envío pasa necesariamente por los proveedores que elegiste (Twilio/Vonage/Infobip, etc.); sus políticas de privacidad se aplican a ese tramo."},{t:"li",v:"Los pagos los procesa Stripe; la identidad, Whaleal IDP. La analítica web de las páginas públicas usa Google Analytics, y solo después de que acepte el aviso de cookies; aparte de estos, no se comparte información con terceros sin su consentimiento."},{t:"li",v:"Bajo el RGPD de la UE/Reino Unido: tú eres el responsable del tratamiento de los datos personales que procesas; la plataforma actúa únicamente como encargada del tratamiento de metadatos SMS siguiendo tus instrucciones. Hay un Acuerdo de Procesamiento de Datos (DPA) disponible a petición a través de support@mail.whaleal.com."},{t:"h2",v:"4. Conservación y eliminación"},{t:"li",v:"Los detalles de clics se conservan 30 días en Free, 90 en Growth, 180 en Pro y 365 en Ultra. El total acumulado de clics se mantiene. Los registros SMS guardan solo metadatos (sin cuerpo del mensaje) y se pueden revisar y exportar a CSV desde la consola."},{t:"li",v:"Eliminar su cuenta borra las credenciales cifradas y los registros de suscripción; los restos en copias de seguridad se limpian dentro del ciclo de rotación de copias (≤30 días)."},{t:"h2",v:"5. Tus derechos"},{t:"p",v:"La recuperación, eliminación, corrección y retirada del consentimiento están disponibles en cualquier momento a través de support@mail.whaleal.com."}]},aup:{title:"Política de Uso Aceptable",meta:{updated:"Última actualización: 2026-09-28",effective:"Vigente desde: 2026-09-28"},blocks:[{t:"p",v:"Esta política establece los límites para el envío a través de la Plataforma. Las infracciones pueden derivar en limitación de velocidad, suspensión y obligaciones de cooperación con las autoridades reguladoras."},{t:"h2",v:"1. Contenido prohibido"},{t:"li",v:"Cualquier actividad ilegal en la jurisdicción del destinatario, incluidos fraude, phishing y distribución de malware."},{t:"li",v:"Mensajería masiva no solicitada; mecanismos de baja falsificados o eludidos."},{t:"li",v:"Contenido para adultos, extremista violento o de odio, y todo lo que los principales proveedores prohíben."},{t:"li",v:"Contenido prohibido por la legislación china aplicable."},{t:"h2",v:"2. Comportamientos prohibidos"},{t:"li",v:"Lavado de números, sondeo masivo de números y actividades similares del mercado gris."},{t:"li",v:"Evasión técnica de límites de velocidad y cuotas (recursos con varias cuentas, inundación por scripts)."},{t:"li",v:"Revender o ceder la Plataforma o sus claves a terceros para envíos masivos."},{t:"h2",v:"3. Obligaciones del remitente"},{t:"li",v:"Cumple con la normativa SMS de cada destino (p. ej., registro A2P 10DLC de TCPA en EE. UU., RGPD de la UE, normas locales de baja)."},{t:"li",v:"Las revisiones del proveedor (plantillas, IDs de remitente, números) las realiza usted en el portal del proveedor."},{t:"h2",v:"4. Aplicación"},{t:"p",v:"Por gravedad: aviso → limitación de velocidad → suspensión de envíos → cierre de cuenta. El uso ilegal se tratará con los reguladores y las fuerzas del orden según corresponda."},{t:"h2",v:"5. Reporte"},{t:"p",v:"Informe de las infracciones a abuse@whaleal.com: las revisamos y actuamos con prontitud."}]}},ja:{terms:{title:"利用規約",meta:{updated:"最終更新日：2026-09-28",effective:"施行日：2026-09-28"},blocks:[{t:"p",v:"本契約は Whaleal Platform（以下「プラットフォーム」）のご利用を規定します。登録またはプラットフォームの利用をもって、本契約を読み同意したものとみなします。"},{t:"h2",v:"1. プラットフォームとは"},{t:"li",v:"本プラットフォームは、自前のキーを持ち込む（BYOL）マルチチャネルSMS中継サービスです。お客様が自社のCPaaSアカウントとキーを提供し、プラットフォームはキー保管、ルーティング、配信確認処理、分析を提供します。"},{t:"li",v:"プラットフォームは SMS を再販せず、キャリア料金にマージンを上乗せしません。キャリア費用はお客様のプロバイダー口座に残ります。有料プランでは、含まれる利用枠を超えた分にプラットフォーム手数料がかかる場合があります（第 4 条）。"},{t:"li",v:"本プラットフォームは基盤となる送信経路を変更しません。メッセージは指定したチャネルを通じてそのまま転送されます。お客様自身のプロバイダーアカウントの状態（滞納、停止、スロットリング）に起因する送信失敗について、本プラットフォームは責任を負いません。"},{t:"li",v:"プラットフォームは配信成功率を保証しません。配信結果はチャンネルとプロバイダーの品質次第であり、プラットフォームはレシートデータをありのまま提示します。"},{t:"h2",v:"2. アカウントとキーのセキュリティ"},{t:"li",v:"プラットフォームのアカウント、API キー、紐づけたプロバイダー認証情報の保護、およびそれらを用いて行われるすべての行為について、お客様が責任を負います。"},{t:"li",v:"認証情報の漏えい、貸与、管理怠慢による損失（それに伴うプロバイダー側の請求を含む）はお客様の負担です。判明次第、ただちにコンソールでキーをローテーションしてください。"},{t:"li",v:"プロバイダーの認証情報は AES-256 で暗号化して保存され、暗号化キーはデータとは別に管理されます。復号は送信時にメモリ上でのみ行われ、ディスクやログに書き出されることはありません。"},{t:"h2",v:"3. 送信に関するお客様の責任"},{t:"li",v:"送信リストが適法に入手され、必要な同意が得られていることを保証してください。送信内容とその適法性（配信停止の処理および各届先の電気通信関連法令の順守を含む）について、お客様が単独で責任を負います。"},{t:"li",v:"届先国の規制を遵守しなかったことに伴う罰金、苦情、法的責任はお客様の負担となります。"},{t:"li",v:"紐づけるプロバイダーキーはすべて適法に取得され、プロバイダーから使用を許可されていることを保証してください。"},{t:"li",v:"プロバイダー側の審査が必要な登録（テンプレート、送信元 ID）は、お客様がプロバイダーのポータルで行います。プラットフォームが代理で申請することはありません。"},{t:"li",v:"苦情、捜査機関からの要請、明らかに違法なコンテンツが判明した場合、プラットフォームは該当アカウントの送信機能を停止または終了し、法に基づき捜査に協力することがあります。"},{t:"h2",v:"4. サブスクリプションと請求"},{t:"li",v:"サブスクリプションは Stripe Checkout で月次または年次に処理され、解約まで各周期で自動更新されます。"},{t:"li",v:"コンソールの「プランと請求」からいつでも解約できます。解約は現在の期間終了時に反映され、それまでは利用できます。"},{t:"li",v:"有料サブスクリプション料金は返金不可です（強制法等で定めがある場合を除く）。Free プランは無期限で利用でき、アップグレード前に評価できます。"},{t:"li",v:"支払い失敗時は 7 日間の猶予期間に入り、その後アカウントは Free に降格します。"},{t:"li",v:"接続数に上限はありません。どのプランにも月間の SMS セグメントと短縮リンククリックが含まれます。Growth 以上は枠を超えても継続でき、超過分にプラットフォーム手数料がかかり、一括 SMS と短縮リンクのインポートも利用できます。キャリアの SMS 料金はお客様のプロバイダー口座に残ります。WhatsApp とメールも含まれます。"},{t:"h2",v:"5. サービスの可用性"},{t:"p",v:"プラットフォームは、途切れのない、エラーのないサービスを保証しません。計画メンテナンス、サードパーティの障害、電気通信ネットワークの障害、不可抗力により生じた損失について、プラットフォームは責任を負いません。ただし、メンテナンス期間は可能な限り事前に通知し、マルチチャネルのフェイルオーバーを誠実に適用します。"},{t:"h2",v:"6. フェアユース"},{t:"p",v:"リソースはティアごとに割り当てられます。継続的な濫用パターン（最大レートでの継続的な負荷、サードパーティのクラスターとのキー共有など）には、連絡、スロットリング、または停止によって対処する場合があります。詳細は Acceptable Use Policy をご覧ください。"},{t:"h2",v:"7. 知的財産権"},{t:"li",v:"プラットフォームのソフトウェア、インターフェース、ドキュメント、商標は運営者の所有です。本契約はサービスの利用に必要な権限のみを付与します。"},{t:"li",v:"プラットフォームで管理するデータ（連絡先、テンプレート、送信履歴、レシートのメタデータ）はお客様のものです。プラットフォームはサービス提供のためにのみ処理します。"},{t:"h2",v:"8. 免責事項および責任制限"},{t:"li",v:"プラットフォームは「現状のまま」提供されます。事業者の障害、通信ネットワークの問題、不可抗力による送信中断または遅延について、プラットフォームは責任を負いません。ただし、影響を緩和するためマルチチャネルのフェイルオーバーを誠実に適用します。"},{t:"li",v:"法律で認められる最大限の範囲で、プラットフォームは間接損失、逸失利益、信用失落、データ損失について責任を負いません。"},{t:"li",v:"プラットフォームの総合責任は、過去12か月間に支払われた購読料を上限とします。"},{t:"h2",v:"9. 終了"},{t:"li",v:"いつでも解約でき、コンソールで自身のデータを確認できます。本規約または適正利用ポリシーに重大な違反があった場合、プラットフォームは通知のうえサービスを停止または終了することがあります。"},{t:"li",v:"未払い：決済失敗は7日間の猶予期間に入り、未払いが続くアカウントはFreeへダウングレードされます（データは削除されません）。"},{t:"li",v:"終了後：暗号化された認証情報とサブスクリプション記録はアカウントとともに削除されます。SMSメタデータは確認とバックアップのため30日間保存され（完全なエクスポートは support@mail.whaleal.com までお問い合わせください）、その後消去されます。"},{t:"li",v:"クリックの詳細は Free で 30 日、Growth で 90 日、Pro で 180 日、Ultra で 365 日保存されます。累計クリック数は残ります。SMS ログはメタデータのみ（本文なし）を保存し、コンソールで確認・CSV エクスポートできます。"},{t:"h2",v:"10. 本規約の変更"},{t:"p",v:"重要な変更は発効の30日前までにメールまたはコンソールで通知します。発効日以降も継続して利用した場合、改訂後の規約に同意したものとみなされます。同意されない場合は利用を停止し、support@mail.whaleal.com まで連絡してデータを取得できます。"},{t:"h2",v:"11. 準拠法および紛争"},{t:"p",v:"本規約はプラットフォーム運営者の登録地の法に準拠します。紛争はまず友好的に解決し、それができない場合は運営者所在地の管轄の仲裁機関または裁判所に付託します。"}]},privacy:{title:"プライバシーポリシー",meta:{updated:"最終更新日：2026-09-28",effective:"施行日：2026-09-28"},blocks:[{t:"p",v:"本ポリシーでは、収集する情報、その理由、保護方法、およびお客様の権利について説明します。一言で言えば、当社はメタデータのみを保存し、メッセージ本文は保存しません。キーは暗号化され、常にお客様のものです。"},{t:"h2",v:"1. 収集する情報"},{t:"li",v:"アカウントデータ：Whaleal IDPログインによるお客様の識別情報（テナントID）とメールアドレス。パスワードは保存せず、ログインはエンタープライズIDサービスが処理します。"},{t:"li",v:"SMSメタデータ：受信者番号、ステータス、タイムスタンプ、プロバイダーエラーコード、チャネルおよび料率の詳細。メッセージ本文は保存しません。"},{t:"li",v:"プロバイダー認証情報：バインドしたAPIキーで、AES-256-GCMにより暗号化されます。コンソールにはマスクされた値のみ表示されます。"},{t:"li",v:"サブスクリプションデータ：Stripeが処理します。カード情報には一切触れず、保存もしません。"},{t:"h2",v:"2. 利用方法"},{t:"li",v:"ルーティング、レシートの書き戻し、利用状況の分析、プラン枠の適用。"},{t:"li",v:"セキュリティ保護と不正利用の防止。"},{t:"li",v:"お客様のデータを販売せず、広告にもモデル学習にも使用しません。"},{t:"h2",v:"3. 共有"},{t:"li",v:"送信は選択したプロバイダー（Twilio／Vonage／Infobipなど）を経由するため、その区間には各社のプライバシーポリシーが適用されます。"},{t:"li",v:"決済は Stripe、認証は Whaleal IDP が処理します。公開ページのアクセス解析には Google Analytics を使用し、Cookie 通知に同意した後でのみ有効になります。これら以外では、お客様の同意なく第三者に開示することはありません。"},{t:"li",v:"EU／UK GDPRに基づき、お客様は処理する個人データのデータ管理者であり、本プラットフォームはお客様の指示に従いSMSメタデータを扱うデータ処理者のみです。データ処理契約（DPA）は support@mail.whaleal.com よりご請求いただけます。"},{t:"h2",v:"4. 保存と削除"},{t:"li",v:"クリックの詳細は Free で 30 日、Growth で 90 日、Pro で 180 日、Ultra で 365 日保存されます。累計クリック数は残ります。SMS ログはメタデータのみ（本文なし）を保存し、コンソールで確認・CSV エクスポートできます。"},{t:"li",v:"アカウントを削除すると、暗号化された認証情報とサブスクリプション記録が削除されます。バックアップの残存データはローテーション期間（30 日以内）内に消去されます。"},{t:"h2",v:"5. お客様の権利"},{t:"p",v:"データの取得、削除、訂正および同意の撤回は、いつでも support@mail.whaleal.com よりご請求いただけます。"}]},aup:{title:"適正利用ポリシー",meta:{updated:"最終更新日：2026-09-28",effective:"施行日：2026-09-28"},blocks:[{t:"p",v:"本ポリシーは、プラットフォーム経由での送信の範囲を定めます。違反した場合、スロットリング、停止、および規制当局との連携義務が生じる可能性があります。"},{t:"h2",v:"1. 禁止コンテンツ"},{t:"li",v:"受信者の管轄地域で違法な行為（詐欺、フィッシング、マルウェア配布など）を含みます。"},{t:"li",v:"同意のない一括送信、配信停止の仕組みの偽装・回避。"},{t:"li",v:"アダルト、暴力・過激、ヘイトを助長するコンテンツ、および主要プロバイダーが禁止するもの。"},{t:"li",v:"中国の関連法で禁止されているコンテンツ。"},{t:"h2",v:"2. 禁止行為"},{t:"li",v:"番号の「洗浄」、大量の番号調査、同様のグレーゾーン行為。"},{t:"li",v:"レート制限や割当量を技術的に回避する行為（複数アカウントの不正利用、スクリプトによる大量負荷など）。"},{t:"li",v:"プラットフォームやキーを第三者に再販・貸与して一括送信させる行為。"},{t:"h2",v:"3. 送信者の義務"},{t:"li",v:"宛先ごとのSMS規制を遵守してください（例：米国TCPA／A2P 10DLC登録、EU GDPR、現地のオプトアウト規則）。"},{t:"li",v:"プロバイダー側の審査（テンプレート、送信元 ID、番号）は、お客様がプロバイダーのポータルで行います。"},{t:"h2",v:"4. 執行"},{t:"p",v:"重大度別：通知 → スロットリング → 送信停止 → アカウント停止。違法な使用は、必要に応じて規制当局および法執行機関とともに処理されます。"},{t:"h2",v:"5. 報告"},{t:"p",v:"違反事項は abuse@whaleal.com までご報告ください。速やかに確認・対応いたします。"}]}},it:{terms:{title:"Termini di servizio",meta:{updated:"Ultimo aggiornamento: 2026-09-28",effective:"In vigore dal: 2026-09-28"},blocks:[{t:"p",v:"Il presente accordo disciplina l’uso di Whaleal Platform (la «Piattaforma»). Registrarsi o utilizzare la Piattaforma significa averlo letto e accettato."},{t:"h2",v:"1. Cos'è la piattaforma"},{t:"li",v:"La piattaforma è un relay SMS multicanale del tipo porta-le-tue-chiavi (BYOL): fornisci tu i tuoi account e chiavi CPaaS; la piattaforma si occupa di custodia delle chiavi, routing, gestione delle ricevute e analisi."},{t:"li",v:"La Piattaforma non rivende SMS e non applica ricarichi alle tariffe dell'operatore. Gli oneri dell'operatore restano sul tuo account provider. Un piano a pagamento può prevedere anche una commissione della piattaforma per l'uso oltre la franchigia inclusa (sezione 4)."},{t:"li",v:"La piattaforma non modifica mai il percorso di invio sottostante: i messaggi vengono inoltrati così come sono attraverso il canale che designi. La piattaforma non è responsabile dei fallimenti di invio causati dallo stato dei tuoi account provider (arretrati, sospensione, limitazione)."},{t:"li",v:"La Piattaforma non garantisce i tassi di consegna. La consegna dipende dalla qualità del canale e del provider; la Piattaforma presenta i dati delle ricevute in modo fedele."},{t:"h2",v:"2. Sicurezza di account e chiavi"},{t:"li",v:"Sei responsabile della protezione del tuo account Piattaforma, delle chiavi API e delle credenziali provider associate, e di tutte le attività che avvengono sotto di esse."},{t:"li",v:"Le perdite causate da perdita, prestito o custodia negligente delle credenziali (compresi gli addebiti da parte del provider) sono a tuo carico. Se scopri un problema, ruota subito le chiavi nella console."},{t:"li",v:"Le credenziali dei provider sono memorizzate crittografate con AES-256; le chiavi di crittografia sono gestite separatamente dai dati, decrittate solo in memoria al momento dell'invio e mai scritte su disco o nei log."},{t:"h2",v:"3. Le tue responsabilità di invio"},{t:"li",v:"Dichiari che le tue liste di invio provengono da fonti lecite e con tutti i consensi necessari, e sei l'unico responsabile del contenuto che invii e della sua legalità, inclusa la gestione dell'opt-out e la conformità telecom di ogni destinazione."},{t:"li",v:"Le sanzioni, i reclami o le responsabilità legali derivanti dal mancato rispetto delle normative del paese di destinazione sono a tuo carico."},{t:"li",v:"Dichiari che tutte le chiavi provider che associ sono ottenute legalmente e autorizzate all'uso da parte del provider."},{t:"li",v:"Le registrazioni che richiedono revisione lato provider (modelli, ID mittente) vengono completate da te nel portale provider; la Piattaforma non le presenta per tuo conto."},{t:"li",v:"In caso di reclami, richieste delle autorità o contenuti chiaramente illeciti, la Piattaforma può sospendere o terminare la capacità di invio dell'account interessato e cooperare con le indagini come richiesto dalla legge."},{t:"h2",v:"4. Abbonamento e fatturazione"},{t:"li",v:"Gli abbonamenti vengono gestiti tramite Stripe Checkout, mensili o annuali, e si rinnovano automaticamente a ogni ciclo fino alla disdetta."},{t:"li",v:"Puoi disdire in qualsiasi momento da Piani e fatturazione nella console; la disdetta ha effetto alla fine del ciclo corrente, con accesso garantito fino ad allora."},{t:"li",v:"Le quote di abbonamento a pagamento non sono rimborsabili (salvo diversa disposizione di legge obbligatoria). Il livello Free è disponibile a tempo indeterminato, così puoi valutare prima di passare a un piano superiore."},{t:"li",v:"I pagamenti non riusciti entrano in un periodo di grazia di 7 giorni; trascorso questo tempo l'account passa a Free."},{t:"li",v:"Le connessioni sono illimitate. Ogni piano include segmenti SMS e clic ai link brevi mensili. I piani Growth e superiori continuano oltre quella franchigia, pagando una commissione della piattaforma per l'uso extra, e includono l'importazione di SMS in blocco e di link brevi. Le tariffe SMS dell'operatore restano sul tuo account provider. WhatsApp ed email sono incluse."},{t:"h2",v:"5. Disponibilità del servizio"},{t:"p",v:"La Piattaforma non garantisce un servizio ininterrotto né privo di errori. La Piattaforma non è responsabile delle perdite causate da manutenzione programmata, interruzioni di terze parti, guasti delle reti di telecomunicazione o forza maggiore, sebbene le finestre di manutenzione vengano annunciate in anticipo quando possibile e venga applicato in buona fede un failover multicanale."},{t:"h2",v:"6. Uso equo"},{t:"p",v:"Le risorse vengono assegnate per livello. Modelli abusivi prolungati (stress continuo a velocità massima, condivisione delle chiavi con cluster di terze parti, ecc.) possono essere gestiti con un contatto diretto, una limitazione della velocità o una sospensione – consulta la Acceptable Use Policy."},{t:"h2",v:"7. Proprietà intellettuale"},{t:"li",v:"Il software, l'interfaccia, la documentazione e i marchi della Piattaforma sono di proprietà dell'operatore della Piattaforma; questo accordo concede solo i diritti necessari a usare il servizio."},{t:"li",v:"I dati che gestisci tramite la Piattaforma (contatti, modelli, record di invio e metadati delle ricevute) ti appartengono; la Piattaforma li tratta esclusivamente per fornire il servizio."},{t:"h2",v:"8. Esclusioni e limitazione di responsabilità"},{t:"li",v:"La Piattaforma è fornita «così come è». Non è responsabile per interruzioni o ritardi causati da guasti del fornitore, reti di telecomunicazione o forza maggiore; viene tuttavia applicato in buona fede un failover multicanale per attenuare l’impatto."},{t:"li",v:"Nella misura massima consentita dalla legge, la Piattaforma non è responsabile per perdite indirette, mancati profitti, avviamento o perdita di dati."},{t:"li",v:"La responsabilità complessiva della Piattaforma è limitata alle quote di abbonamento pagate negli ultimi 12 mesi."},{t:"h2",v:"9. Risoluzione"},{t:"li",v:"Puoi disdire in qualsiasi momento e consultare i tuoi dati nella console. In caso di violazione grave di questi Termini o dell'Informativa sull'uso accettabile, la Piattaforma può sospendere o terminare il servizio dopo aver avvisato."},{t:"li",v:"Mancato pagamento: i pagamenti falliti rientrano in un periodo di grazia di 7 giorni; gli account che restano impagati vengono declassati a Free (i dati non vengono eliminati)."},{t:"li",v:"Dopo la risoluzione: le credenziali crittografate e i dati dell'abbonamento vengono eliminati insieme all'account; i metadati SMS vengono conservati per 30 giorni così puoi controllarli e backupparli (contatta support@mail.whaleal.com per un export completo) e poi cancellati."},{t:"li",v:"I dettagli dei clic vengono conservati 30 giorni su Free, 90 su Growth, 180 su Pro e 365 su Ultra. Il totale dei clic resta per sempre. I log SMS memorizzano solo i metadati (nessun corpo del messaggio) e possono essere consultati ed esportati in CSV dalla console."},{t:"h2",v:"10. Modifiche ai presenti termini"},{t:"p",v:"Le modifiche sostanziali vengono comunicate con 30 giorni di preavviso via e-mail o console. L’uso continuato dopo la data di entrata in vigore costituisce accettazione delle condizioni riviste; se non le accetta, può interrompere l’uso della Piattaforma e contattare support@mail.whaleal.com per recuperare i dati."},{t:"h2",v:"11. Legge applicabile e controversie"},{t:"p",v:"Questi termini sono regolati dalla legge del luogo di registrazione dell'operatore della Piattaforma. Le controversie vengono prima risolte amichevolmente; in mancanza, sono sottoposte all'arbitrato o al tribunale competente del luogo dell'operatore."}]},privacy:{title:"Informativa sulla privacy",meta:{updated:"Ultimo aggiornamento: 2026-09-28",effective:"In vigore dal: 2026-09-28"},blocks:[{t:"p",v:"Questa informativa spiega cosa raccogliamo, perché, come viene protetto e quali sono i tuoi diritti. In breve: memorizziamo solo metadati, mai il contenuto dei messaggi; le chiavi sono crittografate e restano sempre tue."},{t:"h2",v:"1. Cosa raccogliamo"},{t:"li",v:"Dati dell'account: la tua identità dall'accesso con Whaleal IDP (ID tenant) e l'email. Non memorizziamo mai le password — l'accesso è gestito da servizi di identità aziendali."},{t:"li",v:"Metadati SMS: numeri dei destinatari, stato, timestamp, codici di errore del provider, canale e dettagli tariffari. I contenuti dei messaggi non vengono mai memorizzati."},{t:"li",v:"Credenziali provider: le chiavi API che associ, crittografate con AES-256-GCM; la console mostra solo un valore mascherato."},{t:"li",v:"Dati dell'abbonamento: gestiti da Stripe. Non tocchiamo né memorizziamo mai i dati della carta."},{t:"h2",v:"2. Come li utilizziamo"},{t:"li",v:"Routing, riscrittura delle ricevute, analisi dell'uso e applicazione delle quote del piano."},{t:"li",v:"Protezione della sicurezza e prevenzione degli abusi."},{t:"li",v:"Non vendiamo mai i tuoi dati, non li usiamo per pubblicità e non li usiamo per addestrare modelli."},{t:"h2",v:"3. Condivisione"},{t:"li",v:"L'invio passa necessariamente dai provider scelti (Twilio/Vonage/Infobip ecc.); le loro policy sulla privacy si applicano a quella tratta."},{t:"li",v:"I pagamenti sono gestiti da Stripe; l'identità da Whaleal IDP. Le analisi del sito nelle pagine pubbliche usano Google Analytics, e solo dopo che accetti l'informativa sui cookie; oltre a questi, nessuna divulgazione a terzi senza il tuo consenso."},{t:"li",v:"Ai sensi del GDPR UE/UK: sei il titolare del trattamento dei dati personali che tratti; la piattaforma agisce esclusivamente come responsabile del trattamento dei metadati SMS secondo le tue istruzioni. Un Data Processing Agreement (DPA) è disponibile su richiesta tramite support@mail.whaleal.com."},{t:"h2",v:"4. Conservazione ed eliminazione"},{t:"li",v:"I dettagli dei clic vengono conservati 30 giorni su Free, 90 su Growth, 180 su Pro e 365 su Ultra. Il totale dei clic resta per sempre. I log SMS memorizzano solo i metadati (nessun corpo del messaggio) e possono essere consultati ed esportati in CSV dalla console."},{t:"li",v:"L'eliminazione del tuo account rimuove le credenziali crittografate e i record di abbonamento; i residui nei backup vengono cancellati entro la finestra di rotazione dei backup (≤30 giorni)."},{t:"h2",v:"5. I tuoi diritti"},{t:"p",v:"Il recupero, la cancellazione, la rettifica e la revoca del consenso sono disponibili in qualsiasi momento tramite support@mail.whaleal.com."}]},aup:{title:"Informativa sull'uso accettabile",meta:{updated:"Ultimo aggiornamento: 2026-09-28",effective:"In vigore dal: 2026-09-28"},blocks:[{t:"p",v:"Questa informativa definisce i limiti per l'invio tramite la Piattaforma. Le violazioni possono comportare limitazione della velocità, sospensione e obblighi di cooperazione con le autorità di regolamentazione."},{t:"h2",v:"1. Contenuti vietati"},{t:"li",v:"Qualsiasi attività illegale nella giurisdizione del destinatario, inclusi frode, phishing e distribuzione di malware."},{t:"li",v:"Messaggistica di massa non richiesta; meccanismi di opt-out falsificati o aggirati."},{t:"li",v:"Contenuti per adulti, violenti-estremistici o d'odio, e tutto ciò che i principali provider vietano."},{t:"li",v:"Contenuti vietati dalla normativa cinese applicabile."},{t:"h2",v:"2. Comportamenti vietati"},{t:"li",v:"Attività di numerazione illegale, probing di massa dei numeri e simili pratiche grigie."},{t:"li",v:"Evasione tecnica dei limiti di velocità e delle quote (workaround multi-account, flooding automatizzato)."},{t:"li",v:"Rivendere o prestare la Piattaforma o le tue chiavi a terzi per invii in blocco."},{t:"h2",v:"3. Obblighi del mittente"},{t:"li",v:"Rispetta le normative SMS di ogni destinazione (es. registrazione A2P 10DLC del TCPA negli USA, GDPR UE, regole locali di opt-out)."},{t:"li",v:"Le revisioni lato provider (modelli, ID mittente, numeri) vengono completate da te nel portale del provider."},{t:"h2",v:"4. Applicazione"},{t:"p",v:"Per gravità: avviso → limitazione della velocità → sospensione degli invii → chiusura dell'account. L'uso illecito verrà gestito con le autorità di regolamentazione e le forze dell'ordine secondo necessità."},{t:"h2",v:"5. Segnalazione"},{t:"p",v:"Segnala le violazioni a abuse@whaleal.com: esaminiamo e interveniamo tempestivamente."}]}},pt:{terms:{title:"Termos de Serviço",meta:{updated:"Última atualização: 2026-09-28",effective:"Vigente a partir de: 2026-09-28"},blocks:[{t:"p",v:"Este acordo rege a sua utilização da Whaleal Platform (a «Plataforma»). Registar-se ou usar a Plataforma significa que o leu e aceitou."},{t:"h2",v:"1. O que é a plataforma"},{t:"li",v:"A plataforma é um retransmissor de SMS multicanal do tipo traga-suas-próprias-chaves (BYOL): você fornece suas próprias contas e chaves de CPaaS; a plataforma oferece guarda de chaves, roteamento, tratamento de confirmações e análises."},{t:"li",v:"A Plataforma não revende SMS nem acrescenta margem às taxas da operadora. As cobranças da operadora ficam na sua própria conta de provedor. Um plano pago também pode pagar uma taxa da plataforma pelo uso além da franquia incluída (seção 4)."},{t:"li",v:"A plataforma nunca altera o caminho de envio subjacente: as mensagens são encaminhadas como estão pelo canal que você designar. A plataforma não se responsabiliza por falhas de envio causadas pelo estado das suas próprias contas de provedor (atrasos, suspensão, limitação de vazão)."},{t:"li",v:"A Plataforma não garante taxas de entrega. A entrega depende da qualidade do canal e do provedor; a Plataforma apresenta os dados de recibo com fidelidade."},{t:"h2",v:"2. Segurança de conta e chaves"},{t:"li",v:"Você é responsável por proteger sua conta na Plataforma, suas chaves de API e as credenciais de provedor vinculadas, além de toda atividade realizada sob elas."},{t:"li",v:"Perdas causadas por vazamento, empréstimo ou custódia negligente de credenciais (inclusive cobranças decorrentes no provedor) são de sua responsabilidade. Ao descobrir, gire as chaves imediatamente no console."},{t:"li",v:"As credenciais do provedor são armazenadas criptografadas com AES-256; as chaves de criptografia são gerenciadas separadamente dos dados, descriptografadas apenas em memória no momento do envio e nunca gravadas em disco ou logs."},{t:"h2",v:"3. Suas responsabilidades de envio"},{t:"li",v:"Você garante que suas listas de envio têm origem lícita e todos os consentimentos necessários, e é o único responsável pelo conteúdo enviado e sua legalidade, incluindo o tratamento de cancelamentos e a conformidade telecom de cada destino."},{t:"li",v:"Multas, reclamações ou responsabilidades legais decorrentes do descumprimento das normas do país de destino são de sua responsabilidade."},{t:"li",v:"Você garante que todas as chaves de provedor vinculadas foram obtidas legalmente e estão autorizadas pelo provedor."},{t:"li",v:"Cadastros que exigem revisão no provedor (modelos, IDs de remetente) são feitos por você no portal do provedor; a Plataforma não protocola em seu nome."},{t:"li",v:"Diante de reclamações, solicitações de autoridades ou conteúdo claramente ilícito, a Plataforma pode suspender ou encerrar a capacidade de envio da conta envolvida e cooperar com investigações conforme exigido por lei."},{t:"h2",v:"4. Assinatura e cobrança"},{t:"li",v:"As assinaturas são processadas via Stripe Checkout, mensal ou anualmente, e renovam automaticamente a cada ciclo até o cancelamento."},{t:"li",v:"Você pode cancelar a qualquer momento em Planos e Cobrança no console; o cancelamento entra em vigor no fim do ciclo atual, com acesso mantido até lá."},{t:"li",v:"Taxas de assinatura paga não são reembolsáveis (exceto quando a lei obrigatória determinar o contrário). O plano Free está disponível por tempo indeterminado para você avaliar antes de fazer upgrade."},{t:"li",v:"Pagamentos falhos entram em um período de carência de 7 dias; depois disso, a conta é rebaixada para Free."},{t:"li",v:"As conexões são ilimitadas. Todos os planos incluem segmentos de SMS e cliques em links curtos por mês. Growth e acima continuam além da franquia, pagam uma taxa da plataforma pelo uso extra e incluem importação de SMS em massa e de links curtos. As cobranças de SMS da operadora ficam na sua própria conta de provedor. WhatsApp e email estão incluídos."},{t:"h2",v:"5. Disponibilidade do serviço"},{t:"p",v:"A Plataforma não garante um serviço ininterrupto nem livre de erros. A Plataforma não se responsabiliza por perdas causadas por manutenção programada, interrupções de terceiros, falhas nas redes de telecomunicações ou força maior, embora as janelas de manutenção sejam anunciadas com antecedência sempre que possível e seja aplicada de boa-fé uma conmutação multicanal."},{t:"h2",v:"6. Uso justo"},{t:"p",v:"Os recursos são provisionados por nível. Padrões abusivos sustentados (testes contínuos em taxa máxima, compartilhamento de chaves com clusters de terceiros, etc.) podem ser tratados por contato, limitação de taxa ou suspensão – consulte a Acceptable Use Policy."},{t:"h2",v:"7. Propriedade intelectual"},{t:"li",v:"O software, a interface, a documentação e as marcas da Plataforma pertencem ao operador da Plataforma; este acordo concede apenas os direitos necessários para usar o serviço."},{t:"li",v:"Os dados que você gerencia pela Plataforma (contatos, modelos, registros de envio e metadados de recibos) são seus; a Plataforma os processa apenas para prestar o serviço."},{t:"h2",v:"8. Isenções e limitação de responsabilidade"},{t:"li",v:"A Plataforma é fornecida «no estado em que se encontra». Não se responsabiliza por interrupções ou atrasos causados por falha do fornecedor, redes de telecomunicações ou força maior; contudo, é aplicada de boa-fé uma failover multicanal para mitigar o impacto."},{t:"li",v:"No limite máximo permitido por lei, a Plataforma não se responsabiliza por perdas indiretas, lucros cessantes, danos à reputação ou perda de dados."},{t:"li",v:"A responsabilidade agregada da Plataforma está limitada às taxas de assinatura que você pagou nos últimos 12 meses."},{t:"h2",v:"9. Encerramento"},{t:"li",v:"Você pode cancelar a qualquer momento e consultar seus dados no console. Em caso de violação grave destes Termos ou da Política de Uso Aceitável, a Plataforma pode suspender ou encerrar o serviço após aviso."},{t:"li",v:"Não pagamento: pagamentos falhos entram em um período de carência de 7 dias; contas que permanecem sem pagamento são rebaixadas para Free (os dados não são excluídos)."},{t:"li",v:"Após o encerramento: credenciais criptografadas e registros de assinatura são excluídos junto com a conta; os metadados de SMS são mantidos por 30 dias para que você possa revisá-los e fazer backup (entre em contato com support@mail.whaleal.com para uma exportação completa) e, em seguida, são purgados."},{t:"li",v:"Os detalhes de cliques ficam guardados por 30 dias no Free, 90 no Growth, 180 no Pro e 365 no Ultra. O total acumulado de cliques permanece. Os logs de SMS armazenam apenas metadados (sem corpo da mensagem) e podem ser consultados e exportados em CSV no console."},{t:"h2",v:"10. Alterações nestes termos"},{t:"p",v:"As alterações substanciais são notificadas com 30 dias de antecedência por e-mail ou consola. A utilização contínua após a data de eficácia constitui aceitação das condições revistas; se não aceitar, pode deixar de usar a Plataforma e contactar support@mail.whaleal.com para recuperar os seus dados."},{t:"h2",v:"11. Lei aplicável e disputas"},{t:"p",v:"Estes termos são regidos pela lei do local de registro do operador da Plataforma. As disputas devem primeiro ser resolvidas amigavelmente; não sendo possível, serão submetidas à arbitragem ou ao tribunal competente do local do operador."}]},privacy:{title:"Política de Privacidade",meta:{updated:"Última atualização: 2026-09-28",effective:"Vigente a partir de: 2026-09-28"},blocks:[{t:"p",v:"Esta política explica o que coletamos, por quê, como é protegido e quais são os seus direitos. Em uma linha: armazenamos metadados, nunca o corpo das mensagens; as chaves são criptografadas e sempre são suas."},{t:"h2",v:"1. O que coletamos"},{t:"li",v:"Dados da conta: sua identidade do login com Whaleal IDP (ID do locatário) e e-mail. Nunca armazenamos senhas — o login é tratado por serviços de identidade empresariais."},{t:"li",v:"Metadados de SMS: números de destinatários, status, carimbos de data/hora, códigos de erro do provedor, canal e detalhes de tarifa. Os corpos das mensagens nunca são armazenados."},{t:"li",v:"Credenciais de provedor: as chaves de API que você vincula, criptografadas com AES-256-GCM; o console mostra apenas um valor mascarado."},{t:"li",v:"Dados de assinatura: processados pela Stripe. Nunca tocamos nem armazenamos dados de cartão."},{t:"h2",v:"2. Como usamos"},{t:"li",v:"Roteamento, gravação de recibos, análise de uso e aplicação da cota do plano."},{t:"li",v:"Proteção de segurança e prevenção de abusos."},{t:"li",v:"Nunca vendemos seus dados, nunca os usamos para publicidade e nunca os usamos para treinar modelos."},{t:"h2",v:"3. Compartilhamento"},{t:"li",v:"O envio passa necessariamente pelos provedores que você escolheu (Twilio/Vonage/Infobip etc.); as políticas de privacidade deles se aplicam a essa etapa."},{t:"li",v:"Pagamentos são processados pela Stripe; identidade, pelo Whaleal IDP. A análise de tráfego nas páginas públicas usa o Google Analytics, e somente depois de você aceitar o aviso de cookies; fora isso, nenhuma divulgação a terceiros sem seu consentimento."},{t:"li",v:"Sob o GDPR da UE/Reino Unido: você é o controlador dos dados pessoais que processa; a plataforma atua apenas como operadora de dados, tratando metadados de SMS conforme suas instruções. Um Acordo de Processamento de Dados (DPA) está disponível mediante solicitação via support@mail.whaleal.com."},{t:"h2",v:"4. Retenção e exclusão"},{t:"li",v:"Os detalhes de cliques ficam guardados por 30 dias no Free, 90 no Growth, 180 no Pro e 365 no Ultra. O total acumulado de cliques permanece. Os logs de SMS armazenam apenas metadados (sem corpo da mensagem) e podem ser consultados e exportados em CSV no console."},{t:"li",v:"Excluir sua conta remove as credenciais criptografadas e os registros de assinatura; resíduos em backup são limpos dentro da janela de rotação de backups (≤30 dias)."},{t:"h2",v:"5. Seus direitos"},{t:"p",v:"A recuperação, eliminação, correção e retirada do consentimento estão disponíveis a qualquer momento através de support@mail.whaleal.com."}]},aup:{title:"Política de Uso Aceitável",meta:{updated:"Última atualização: 2026-09-28",effective:"Vigente a partir de: 2026-09-28"},blocks:[{t:"p",v:"Esta política define os limites para o envio pela Plataforma. Violações podem levar à limitação de taxa, suspensão e obrigações de cooperação com órgãos reguladores."},{t:"h2",v:"1. Conteúdo proibido"},{t:"li",v:"Qualquer atividade ilegal na jurisdição do destinatário, incluindo fraude, phishing e distribuição de malware."},{t:"li",v:"Mensagens em massa não solicitadas; mecanismos de cancelamento falsificados ou burlados."},{t:"li",v:"Conteúdo adulto, extremista-violento ou de ódio, e tudo o que os principais provedores proíbem."},{t:"li",v:"Conteúdo proibido pela legislação chinesa aplicável."},{t:"h2",v:"2. Comportamentos proibidos"},{t:"li",v:"Lavagem de números, sondagem em massa de números e atividades semelhantes do mercado cinza."},{t:"li",v:"Evasão técnica de limites de taxa e cotas (artifícios com múltiplas contas, inundação por scripts)."},{t:"li",v:"Revender ou emprestar a Plataforma ou suas chaves a terceiros para envios em massa."},{t:"h2",v:"3. Obrigações do remetente"},{t:"li",v:"Cumpra as normas de SMS de cada destino (ex.: registro A2P 10DLC da TCPA nos EUA, GDPR da UE, regras locais de opt-out)."},{t:"li",v:"As revisões no provedor (modelos, IDs de remetente, números) são feitas por você no portal do provedor."},{t:"h2",v:"4. Aplicação"},{t:"p",v:"Por gravidade: aviso → limitação de taxa → suspensão de envios → encerramento da conta. O uso ilegal será tratado com os reguladores e as autoridades policiais conforme necessário."},{t:"h2",v:"5. Denúncia"},{t:"p",v:"Reporte violações para abuse@whaleal.com — analisamos e agimos prontamente."}]}},ko:{terms:{title:"이용 약관",meta:{updated:"최종 업데이트: 2026-09-28",effective:"시행일: 2026-09-28"},blocks:[{t:"p",v:"본 계약은 Whaleal Platform(이하 “플랫폼”) 사용에관한 규정입니다. 등록 또는 플랫폼 사용은 본 계약을 읽고 동의했음을 의미합니다."},{t:"h2",v:"1. 플랫폼이란"},{t:"li",v:"본 플랫폼은 자체 키 가져오기(BYOL) 방식의 다채널 SMS 중계 서비스입니다. 고객이 직접 CPaaS 계정과 키를 제공하고, 플랫폼은 키 보관, 라우팅, 수신 확인 처리, 분석을 제공합니다."},{t:"li",v:"플랫폼은 SMS를 재판매하거나 통신사 요금에 마진을 붙이지 않습니다. 통신사 요금은 고객의 공급자 계정에 남습니다. 유료 요금제는 포함된 할당량을 넘은 사용분에 플랫폼 수수료가 부과될 수 있습니다(제4조)."},{t:"li",v:"본 플랫폼은 기본 전송 경로를 변경하지 않습니다. 메시지는 지정한 채널을 통해 그대로 전달됩니다. 고객 본인의 제공업체 계정 상태(연체, 정지, 속도 제한)로 인한 전송 실패에 대해 플랫폼은 책임지지 않습니다."},{t:"li",v:"플랫폼은 전달률을 보장하지 않습니다. 전달은 채널과 공급자 품질에 따라 달라지며, 플랫폼은 수신 확인 데이터를 그대로 제공합니다."},{t:"h2",v:"2. 계정 및 키 보안"},{t:"li",v:"플랫폼 계정, API 키, 연결된 공급자 자격 증명을 안전하게 보호하고 그 아래에서 발생하는 모든 활동에 대해 책임집니다."},{t:"li",v:"자격 증명 유출, 대여, 부실 보관으로 인한 손실(공급자 측 요금 포함)은 고객이 부담합니다. 발견 즉시 콘솔에서 키를 교체하세요."},{t:"li",v:"공급자 자격 증명은 AES-256으로 암호화 저장됩니다. 암호화 키는 데이터와 분리 관리되며, 발송 시에만 메모리에서 복호화되고 디스크나 로그에 기록되지 않습니다."},{t:"h2",v:"3. 전송에 관한 고객의 책임"},{t:"li",v:"발송 목록이 필요한 모든 동의를 받아 적법하게 확보되었음을 보증하며, 발송 콘텐츠와 그 적법성(수신 거부 처리 및 목적지별 통신 규정 준수 포함)에 대한 책임은 전적으로 고객에게 있습니다."},{t:"li",v:"목적지 국가 규정을 준수하지 않아 발생하는 벌금, 민원 또는 법적 책임은 고객이 부담합니다."},{t:"li",v:"연결하는 모든 공급자 키가 적법하게 취득되었고 공급자로부터 사용 권한을 받았음을 보증합니다."},{t:"li",v:"공급자 심사가 필요한 등록(템플릿, 발신자 ID)은 공급자 포털에서 고객이 직접 진행합니다. 플랫폼이 대신 신청하지 않습니다."},{t:"li",v:"민원, 수사기관 요청 또는 명백히 불법인 콘텐츠가 있을 경우, 플랫폼은 해당 계정의 발송 기능을 중단 또는 종료하고 법에 따라 수사에 협조할 수 있습니다."},{t:"h2",v:"4. 구독 및 결제"},{t:"li",v:"구독은 Stripe Checkout에서 월간 또는 연간으로 처리되며, 해지할 때까지 매 주기마다 자동 갱신됩니다."},{t:"li",v:"콘솔의 요금제 및 결제에서 언제든 해지할 수 있습니다. 해지는 현재 이용 기간 종료 시 적용되며 그 전까지 이용 권한은 유지됩니다."},{t:"li",v:"유료 구독료는 환불되지 않습니다(강행 법규에 따라 환불해야 하는 경우 제외). Free 요금제는 무기한 제공되므로 업그레이드 전에 충분히 평가할 수 있습니다."},{t:"li",v:"결제 실패 시 7일의 유예 기간이 적용되며, 이후 계정은 Free로 강등됩니다."},{t:"li",v:"연결 수는 무제한입니다. 모든 요금제에 월간 SMS 세그먼트와 짧은 링크 클릭이 포함됩니다. Growth 이상은 할당량을 초과해 사용하고 추가 사용분에 플랫폼 수수료를 내며, 대량 SMS와 짧은 링크 가져오기가 포함됩니다. 통신사 SMS 요금은 고객의 공급자 계정에 남습니다. WhatsApp과 이메일은 포함됩니다."},{t:"h2",v:"5. 서비스 가용성"},{t:"p",v:"플랫폼은 중단 없이 오류 없이 서비스를 제공할 것을 보장하지 않습니다. 예정된 유지보수, 타사 장애, 통신 네트워크 장애 또는 불가항력으로 인한 손실에 대해 플랫폼은 책임지지 않습니다. 단, 유지보수 창은 가능한 경우 사전에 공지하며, 다중 채널 페일오버를 성실히 적용합니다."},{t:"h2",v:"6. 공정 사용"},{t:"p",v:"리소스는 등급별로 프로비저닝됩니다. 지속적인 남용 패턴(지속적인 최대 속도 부하, 타사 클러스터와 키 공유 등)은 연락, 속도 제한 또는 정지를 통해 조치될 수 있습니다. 자세한 내용은 Acceptable Use Policy를 참조하세요."},{t:"h2",v:"7. 지식재산권"},{t:"li",v:"플랫폼 소프트웨어, 인터페이스, 문서, 상표는 플랫폼 운영자의 소유입니다. 본 계약은 서비스 이용에 필요한 권한만 부여합니다."},{t:"li",v:"플랫폼을 통해 관리하는 데이터(연락처, 템플릿, 발송 기록, 수신 확인 메타데이터)는 고객의 소유입니다. 플랫폼은 서비스 제공을 위해서만 이를 처리합니다."},{t:"h2",v:"8. 면책 및 책임 제한"},{t:"li",v:"플랫폼은 “있는 그대로” 제공됩니다. 공급자 장애, 통신 네트워크 문제 또는 불가항력으로 인한 중단이나 지연에 대해 플랫폼은 책임지지 않으나, 영향을 줄이기 위해 다중 채널 장애 조치를 성실히 적용합니다."},{t:"li",v:"법률이 허용하는 최대 범위 내에서, 플랫폼은 간접 손실, 영업이익 상실, 신용 훼손 또는 데이터 손실에 대해 책임지지 않습니다."},{t:"li",v:"플랫폼의 총 책임은 최근 12개월 동안 지급한 구독료를 한도로 합니다."},{t:"h2",v:"9. 종료"},{t:"li",v:"언제든 해지할 수 있고 콘솔에서 자체 데이터를 확인할 수 있습니다. 본 약관이나 이용 수칙을 중대하게 위반할 경우 플랫폼은 사전 통지 후 서비스를 중단 또는 종료할 수 있습니다."},{t:"li",v:"미납: 결제 실패 시 7일의 유예 기간이 적용되며, 미납 상태가 지속되는 계정은 Free로 강등됩니다(데이터는 삭제되지 않습니다)."},{t:"li",v:"종료 후: 암호화된 자격 증명과 구독 기록은 계정과 함께 삭제됩니다. SMS 메타데이터는 검토와 백업을 위해 30일간 보관된 뒤(전체 내보내기는 support@mail.whaleal.com으로 문의) 정리됩니다."},{t:"li",v:"클릭 상세는 Free에서 30일, Growth에서 90일, Pro에서 180일, Ultra에서 365일 보관됩니다. 누적 클릭 수는 계속 유지됩니다. SMS 로그에는 메타데이터만 저장되고(본문 없음) 콘솔에서 조회 및 CSV 내보내기가 가능합니다."},{t:"h2",v:"10. 본 약관의 변경"},{t:"p",v:"중요한 변경 사항은 시행 30일 전에 이메일 또는 콘솔로 안내합니다. 시행일 이후에도 계속 이용하면 개정된 약관에 동의한 것으로 간주됩니다. 동의하지 않는 경우 플랫폼 사용을 중단하고 support@mail.whaleal.com으로 문의하여 데이터를 회수할 수 있습니다."},{t:"h2",v:"11. 준거법 및 분쟁"},{t:"p",v:"본 약관은 플랫폼 운영자의 등록지 법률에 따릅니다. 분쟁은 우선 원만히 해결하며, 해결되지 않을 경우 운영자 소재지의 관할 중재기관 또는 법원에 제출합니다."}]},privacy:{title:"개인정보 처리방침",meta:{updated:"최종 업데이트: 2026-09-28",effective:"시행일: 2026-09-28"},blocks:[{t:"p",v:"본 정책은 수집 항목, 수집 이유, 보호 방법 및 사용자의 권리를 설명합니다. 한 줄로 요약하면, 우리는 메타데이터만 저장하고 메시지 본문은 저장하지 않으며, 키는 암호화되어 항상 사용자의 소유입니다."},{t:"h2",v:"1. 수집 항목"},{t:"li",v:"계정 데이터: Whaleal IDP 로그인을 통한 고객 신원(테넌트 ID)과 이메일. 비밀번호는 저장하지 않으며, 로그인은 기업 신원 서비스에서 처리합니다."},{t:"li",v:"SMS 메타데이터: 수신자 번호, 상태, 타임스탬프, 제공업체 오류 코드, 채널 및 요금 상세. 메시지 본문은 저장하지 않습니다."},{t:"li",v:"제공업체 자격 증명: 연결한 API 키로, AES-256-GCM으로 암호화됩니다. 콘솔에는 마스킹된 값만 표시됩니다."},{t:"li",v:"구독 데이터: Stripe에서 처리합니다. 카드 정보는 만지거나 저장하지 않습니다."},{t:"h2",v:"2. 이용 방식"},{t:"li",v:"라우팅, 수신 확인 기록, 사용량 분석, 요금제 할당량 적용."},{t:"li",v:"보안 보호 및 남용 방지."},{t:"li",v:"고객 데이터를 판매하거나 광고에 사용하지 않으며, 모델 학습에도 쓰지 않습니다."},{t:"h2",v:"3. 공유"},{t:"li",v:"전송은 선택한 제공업체(Twilio/Vonage/Infobip 등)를 거칠 수밖에 없으며, 해당 구간에는 그들의 개인정보 처리방침이 적용됩니다."},{t:"li",v:"결제는 Stripe, 신원 인증은 Whaleal IDP가 처리합니다. 공개 페이지의 웹사이트 분석은 쿠키 안내에 동의한 후에만 Google Analytics를 사용합니다. 이 외에는 동의 없이 제3자에게 정보를 제공하지 않습니다."},{t:"li",v:"EU/UK GDPR에 따라, 고객은 처리하는 개인정보의 데이터 관리자이며, 플랫폼은 고객의 지시에 따라 SMS 메타데이터를 처리하는 데이터 처리자일 뿐입니다. 데이터 처리 계약(DPA)은 support@mail.whaleal.com을 통해 요청 시 제공됩니다."},{t:"h2",v:"4. 보관 및 삭제"},{t:"li",v:"클릭 상세는 Free에서 30일, Growth에서 90일, Pro에서 180일, Ultra에서 365일 보관됩니다. 누적 클릭 수는 계속 유지됩니다. SMS 로그에는 메타데이터만 저장되고(본문 없음) 콘솔에서 조회 및 CSV 내보내기가 가능합니다."},{t:"li",v:"계정을 삭제하면 암호화된 자격 증명과 구독 기록이 제거되며, 백업 잔여 데이터는 백업 순환 주기(30일 이내) 안에 정리됩니다."},{t:"h2",v:"5. 고객의 권리"},{t:"p",v:"데이터 회수·삭제·정정 및 동의 철회는 언제든지 support@mail.whaleal.com을 통해 요청할 수 있습니다."}]},aup:{title:"이용 수칙",meta:{updated:"최종 업데이트: 2026-09-28",effective:"시행일: 2026-09-28"},blocks:[{t:"p",v:"본 정책은 플랫폼을 통한 발송의 경계를 정의합니다. 위반 시 속도 제한, 발송 정지 및 규제 기관과의 협력 의무가 발생할 수 있습니다."},{t:"h2",v:"1. 금지 콘텐츠"},{t:"li",v:"수신자가 있는 관할 지역에서 불법인 모든 행위(사기, 피싱, 악성코드 유포 등)를 포함합니다."},{t:"li",v:"원치 않는 대량 메시지 발송, 수신 거부 메커니즘을 위조하거나 우회하는 행위."},{t:"li",v:"성인물, 폭력적·극단적 또는 혐오 콘텐츠, 그리고 주요 공급자가 금지하는 모든 콘텐츠."},{t:"li",v:"관련 중국 법률에 따라 금지된 콘텐츠."},{t:"h2",v:"2. 금지 행위"},{t:"li",v:"번호 세탁, 대량 번호 탐지 및 유사한 회색 시장 활동."},{t:"li",v:"속도 제한과 할당량을 기술적으로 회피하는 행위(다중 계정 우회, 스크립트 부하 폭주)."},{t:"li",v:"플랫폼이나 키를 제3자에게 재판매하거나 대여해 대량 발송에 사용하는 행위."},{t:"h2",v:"3. 발신자 의무"},{t:"li",v:"목적지별 SMS 규정을 준수하세요(예: 미국 TCPA/A2P 10DLC 등록, EU GDPR, 현지 수신 거부 규정)."},{t:"li",v:"공급자 측 심사(템플릿, 발신자 ID, 번호)는 공급자 포털에서 고객이 직접 진행합니다."},{t:"h2",v:"4. 집행"},{t:"p",v:"심각도에 따라: 통지 → 속도 제한 → 발송 정지 → 계정 종료. 불법 사용은 필요에 따라 규제 기관 및 수사 기관과 함께 처리됩니다."},{t:"h2",v:"5. 신고"},{t:"p",v:"위반 사항은 abuse@whaleal.com으로 신고해 주세요. 신속히 검토하여 조치하겠습니다."}]}},"zh-Hant":{terms:{title:"服務條款",meta:{updated:"最後更新：2026-09-28",effective:"生效日期：2026-09-28"},blocks:[{t:"p",v:"本協議規範您使用 Whaleal Platform（下稱「平台」）。註冊或使用平台即表示您已閱讀並同意本協議。"},{t:"h2",v:"1. 平台是什麼"},{t:"li",v:"本平台是「自備金鑰」（BYOL）的多通道簡訊中繼服務：您提供自己的 CPaaS 帳號與金鑰；平台提供金鑰保管、路由、回執處理與分析。"},{t:"li",v:"平台不轉售 SMS，也不加價電信業者費率。電信費用留在你自己的供應商帳號。付費方案另可對超出包含的額度用量支付平台費（第 4 節）。"},{t:"li",v:"平台絕不改變底層發送路徑：訊息會依您指定的通道原樣轉送。對於因您自己供應商帳號狀態（欠款、停用、限速）造成的發送失敗，平台不負責任。"},{t:"li",v:"平台不保證送達率。送達取決於通道與供應商品質；平台如實呈現回執資料。"},{t:"h2",v:"2. 帳號與金鑰安全"},{t:"li",v:"你有責任妥善保管平台帳號、API 金鑰與已綁定的供應商憑證，以及其下所有活動。"},{t:"li",v:"因憑證洩漏、外借或保管疏忽造成的損失（包括因而產生的供應商端費用）由你承擔。一旦發現，請立即在主控台輪替金鑰。"},{t:"li",v:"供應商憑證以 AES-256 加密儲存；加密金鑰與資料分開管理，僅在寄送時於記憶體中解密，永不寫入磁碟或紀錄。"},{t:"h2",v:"3. 您的發送責任"},{t:"li",v:"你保證寄送名單來源合法並取得所有必要同意，且對所寄內容及其合法性負全責，包括退訂處理與各目的地的電信合規。"},{t:"li",v:"因未遵守目的地國家法規而產生的罰款、申訴或法律責任，由你自行承擔。"},{t:"li",v:"你保證所綁定的所有供應商金鑰均合法取得，並獲供應商授權使用。"},{t:"li",v:"需要供應商審核的登錄（範本、寄件者 ID）由你在供應商後台完成；平台不代為送件。"},{t:"li",v:"接獲申訴、執法機關要求或明顯違法內容時，平台得暫停或終止相關帳號的寄送功能，並依法配合調查。"},{t:"h2",v:"4. 訂閱與計費"},{t:"li",v:"訂閱透過 Stripe Checkout 處理，可選月繳或年繳，每個週期自動續訂直到取消為止。"},{t:"li",v:"你可隨時在主控台的『方案與計費』取消；取消於當前週期結束時生效，在此之前使用權不受影響。"},{t:"li",v:"付費訂閱費用恕不退費（強制法規另有規定者除外）。免費方案可無限期使用，讓你評估後再升級。"},{t:"li",v:"付款失敗進入 7 天寬限期；之後帳號降為免費版。"},{t:"li",v:"連線數無上限。每個方案都包含每月 SMS 段數與短連結點擊。成長版及以上可超越額度，為額外用量支付平台費，並包含大量 SMS 與短連結匯入。電信業者 SMS 費用仍留在你自己的供應商帳號。WhatsApp 與郵件已包含。"},{t:"h2",v:"5. 服務可用性"},{t:"p",v:"平台不保證服務不中斷或完全無誤。對於因排定維護、第三方服務中斷、電信網路故障或不可抗力所造成的損失，平台不負賠償責任；不過維護時段會盡可能事先公告，並本於誠信原則採用多通道容錯移轉。"},{t:"h2",v:"6. 合理使用"},{t:"p",v:"資源依方案配置。持續性的濫用行為（持續以最大速率進行壓力測試、與第三方叢集共用金鑰等）可能透過聯繫、限流或停用等方式處理——請參閱 Acceptable Use Policy。"},{t:"h2",v:"7. 智慧財產權"},{t:"li",v:"平台軟體、介面、文件與商標由平台營運方擁有；本協議僅授予使用服務所需的權利。"},{t:"li",v:"你透過平台管理的資料（聯絡人、範本、寄送紀錄與回執中繼資料）歸你所有；平台僅為提供服務而處理。"},{t:"h2",v:"8. 免責聲明與責任限制"},{t:"li",v:"平台按「現狀」提供服務。對因供應商故障、電信網路問題、不可抗力導致的傳送中斷或延遲，平台不承擔責任，但將盡力透過多渠道容災降低影響。"},{t:"li",v:"在法律允許的最大範圍內，平台不對任何間接損失、利潤損失、商譽或資料遺失負責。"},{t:"li",v:"平台的累計責任上限，以您過去 12 個月已支付的訂閱費用為限。"},{t:"h2",v:"9. 終止"},{t:"li",v:"你可隨時取消，並在主控台檢視自己的資料。若重大違反本條款或可接受使用政策，平台得於通知後暫停或終止服務。"},{t:"li",v:"未付款：付款失敗進入 7 天寬限期；持續未付款的帳號將降級為 Free（資料不會刪除）。"},{t:"li",v:"終止後：加密憑證與訂閱紀錄會隨帳號一併刪除；簡訊中繼資料保留 30 天供您檢視與備份（如需完整匯出請聯繫 support@mail.whaleal.com），之後清除。"},{t:"li",v:"點擊詳情在自由版保留 30 天、成長版 90 天、專業版 180 天、旗艦版 365 天。累計點擊總數永久保留。SMS 紀錄僅儲存中繼資料（不含訊息內文），可在主控台檢視並匯出為 CSV。"},{t:"h2",v:"10. 本條款變更"},{t:"p",v:"重大變更將提前 30 天透過郵件或控制台通知。變更生效後您繼續使用平台，即視為接受修訂後的協議；不接受的可停止使用，並可聯絡 support@mail.whaleal.com 取回資料。"},{t:"h2",v:"11. 準據法與爭議"},{t:"p",v:"本條款適用平台營運商註冊地的法律。爭議應先友好協商解決；協商不成，則提交營運所在地具管轄權的仲裁機構或法院。"}]},privacy:{title:"隱私權政策",meta:{updated:"最後更新：2026-09-28",effective:"生效日期：2026-09-28"},blocks:[{t:"p",v:"本政策說明我們蒐集哪些資料、原因、保護方式，以及您的權利。一句話來說：我們只儲存中繼資料，絕不儲存訊息內容；金鑰均經過加密，且始終為您所有。"},{t:"h2",v:"1. 我們收集哪些資料"},{t:"li",v:"帳號資料：您透過 Whaleal IDP 登入的識別資訊（租戶 ID）與電子郵件。我們從不儲存密碼 — 登入由企業身分服務處理。"},{t:"li",v:"簡訊中繼資料：收件號碼、狀態、時間戳記、供應商錯誤代碼、通道與費率詳情。訊息內容永不儲存。"},{t:"li",v:"供應商憑證：您綁定的 API 金鑰，以 AES-256-GCM 加密；控制台一律只顯示遮罩後的值。"},{t:"li",v:"訂閱資料：由 Stripe 處理。我們絕不碰觸或儲存卡片資料。"},{t:"h2",v:"2. 我們如何使用"},{t:"li",v:"路由、回執寫回、用量分析與方案配額執行。"},{t:"li",v:"安全防護與濫用防治。"},{t:"li",v:"我們永不販售你的資料、永不拿來打廣告，也永不用於訓練模型。"},{t:"h2",v:"3. 分享"},{t:"li",v:"發送必然經過您選擇的供應商（Twilio／Vonage／Infobip 等）；該環節適用其隱私權政策。"},{t:"li",v:"付款由 Stripe 處理；身分由 Whaleal IDP 驗證。公開頁面的網站分析使用 Google Analytics，且僅在你接受 Cookie 通知後啟用；除此之外，未經你同意不向第三方揭露。"},{t:"li",v:"依 EU／UK GDPR：您對所處理的個人資料為資料控制者；平台僅作為資料處理者，依您的指示處理簡訊中繼資料。資料處理協議（DPA）可透過 support@mail.whaleal.com 索取。"},{t:"h2",v:"4. 保留與刪除"},{t:"li",v:"點擊詳情在自由版保留 30 天、成長版 90 天、專業版 180 天、旗艦版 365 天。累計點擊總數永久保留。SMS 紀錄僅儲存中繼資料（不含訊息內文），可在主控台檢視並匯出為 CSV。"},{t:"li",v:"刪除帳號會移除加密憑證與訂閱紀錄；備份殘留會在備份輪替週期內清除（≤30 天）。"},{t:"h2",v:"5. 您的權利"},{t:"p",v:"您可隨時要求取回或刪除資料、更正資訊、撤銷同意。行使權利請聯絡 support@mail.whaleal.com。"}]},aup:{title:"可接受使用政策",meta:{updated:"最後更新：2026-09-28",effective:"生效日期：2026-09-28"},blocks:[{t:"p",v:"本政策訂定透過平台傳送的界限。違反規定可能導致限流、停用，以及配合監理機關的義務。"},{t:"h2",v:"1. 禁止內容"},{t:"li",v:"收件人所在地區任何違法的行為，包括詐騙、網路釣魚與散播惡意軟體。"},{t:"li",v:"未經請求的大量訊息；偽造或規避退訂機制。"},{t:"li",v:"成人、暴力極端或仇恨內容，以及主要供應商禁止的任何內容。"},{t:"li",v:"適用中國法律所禁止的內容。"},{t:"h2",v:"2. 禁止行為"},{t:"li",v:"號碼洗白、大量號碼探測及類似灰市行為。"},{t:"li",v:"以技術手段規避速率限制與配額（多帳號變通、腳本壓力灌爆）。"},{t:"li",v:"將平台或你的金鑰轉售、出借給第三方進行大量寄送。"},{t:"h2",v:"3. 發送方義務"},{t:"li",v:"遵守各目的地國家的簡訊法規（例如美國 TCPA／A2P 10DLC 註冊、EU GDPR、在地退出規則）。"},{t:"li",v:"供應商端的審核（範本、寄件者 ID、號碼）由你在供應商後台完成。"},{t:"h2",v:"4. 執行"},{t:"p",v:"依情節輕重：通知 → 限流 → 暫停傳送 → 終止帳號。違法使用將依規定與監理機關及執法單位處理。"},{t:"h2",v:"5. 檢舉"},{t:"p",v:"發現違規內容請舉報至 abuse@whaleal.com，我們會及時核查處理。"}]}}};var r=t(1914),l=t(8799);const d=new Set(["zh","zh-Hant"]);function c({block:e}){const a=e.v;return"h2"===e.t?i.createElement("h2",null,a):"h3"===e.t?i.createElement("h3",null,a):"li"===e.t?i.createElement("li",null,a):i.createElement("p",null,a)}function u({pageContext:e}){var a;const{locale:t}=(0,r.Xw)(e),u=t||"en",p=e.kind,v=(n[u]||n.en)[p],m=v.blocks,h=`/legal/${p}/`,g=d.has(u)?"鲸联":"Whaleal",f=`${v.title} — ${g}`;return i.createElement(o.A,{locale:null==e?void 0:e.locale},i.createElement(s.A,{title:f,description:(null===(a=v.blocks.find(e=>"p"===e.t))||void 0===a?void 0:a.v)||v.title,pathname:h,canonicalPath:(0,l.MF)(h,u),softwareApp:!1,breadcrumbs:[{name:"zh"===u?"首页":"Home",path:(0,l.MF)("/",u)},{name:v.title,path:(0,l.MF)(h,u)}],hrefLang:u}),i.createElement("div",{className:"page-container about-page"},i.createElement("div",{className:"page-header about-header"},i.createElement("h1",null,v.title),i.createElement("p",null,v.meta.updated," · ",v.meta.effective)),i.createElement("div",{className:"about-content"},m.map((e,a)=>i.createElement(c,{key:a,block:e})))))}}}]);
